\label{thm:balanced_clt}
	Let $0<\beta^2<\alpha_c(\kappa)$ and let $(\boldsymbol{n}_N)$ be a sequence of profiles with $\sup_N\left\Vertm_{\boldsymbol{n}_N}\right\Vert_2<\infty$. Then, as $N\to\infty$,
	\begin{align*}
		&\ln Z_N^{(\boldsymbol{n}_N)}(\beta)-\ln\left\vert\Sigma_N^{(\boldsymbol{n}_N)}\right\vert
			-\frac{\beta^2(\kappa-1)}4(N-\kappa+1)-\frac\alpha2\left\Vertm_{\boldsymbol{n}_N}\right\Vert_2^2\\
		&\quad\Longrightarrow
		\operatorname{N}\left(-\frac12\varphi_\kappa(\beta^2)
			+\frac{\mu_4\beta^4(\kappa-1)(\kappa^2-6\kappa+6)}{48},
			\ \varphi_{\kappa,J}(\beta^2)\right).
	\end{align*}

\label{thm:full_clt}
	Let $0<\beta<\beta_{\max}(\kappa)$. Then, as $N\to\infty$,
	\begin{align*}
		&\ln Z_N(\beta)-N\ln\kappa-\frac{\beta^2(\kappa-1)}4(N-1)\\
		&\quad\Longrightarrow
		\operatorname{N}\left((\kappa-1)\varphi(\alpha)-\frac12\varphi_\kappa(\beta^2)
			+\frac{\mu_4\beta^4(\kappa-1)(\kappa^2-6\kappa+6)}{48},
			\ \varphi_{\kappa,J}(\beta^2)\right).
	\end{align*}

\label{thm:C}
	Let $0<\beta<\beta_{\max}(\kappa)$, and let
    \[
    g,g'\sim\operatorname{N}\big(0,\Pi/(1-\alpha)\big)\quad\text{and}\quad K\sim\operatorname{N}\big(0,\Pi\otimes\Pi/(1-\beta^2)\big)
    \]
    be independent. Then, for every bounded continuous $F$ on $\mathds{R}^\kappa\times\mathds{R}^\kappa\times\mathds{R}^{\kappa\times\kappa}$,
	\begin{align*}
		\left\langle F\big(m(\boldsymbol{\sigma}^1),m(\boldsymbol{\sigma}^2),\mathscr{R}(\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2)\big)
			\right\rangle_{\varrho_{N,\beta}^{\otimes2}}
		\longrightarrow \operatorname{\mathds{E}}\big(F(g,g',K)\big)
		\quad\text{in probability}.
	\end{align*}

\label{rem:special-cases}
	\begin{enumeratea}
	    \item Theorem~\ref{thm:balanced_clt} applies to $Z_N^{\operatorname{bal}}$ along $\kappa\mid N$, where $m_{\boldsymbol{n}^*}=0$. It also applies to $Z_N^{(\boldsymbol{n}^*)}$ for every $N$, where the magnetization correction vanishes in the limit.
        \item For Gaussian disorder $\mu_4=0$, so $\varphi_{\kappa,J}=\varphi_\kappa$ and the fourth-cumulant term in the mean vanishes.
        \item For $\kappa=2$ we have $\alpha=0$, $\alpha_c(2)=\beta_{\max}(2)=1$, and $\varphi_2=\varphi$. For Gaussian disorder, Theorem~\ref{thm:full_clt} then states that $\ln Z_N(\beta)-N\ln2-\beta^2(N-1)/4\Longrightarrow\operatorname{N}\big(-\tfrac12\varphi(\beta^2),\varphi(\beta^2)\big)$ for $\beta<1$. This is the central limit theorem of Aizenman, Lebowitz and Ruelle~\cite{ALR87} for the SK model. For Rademacher couplings $\operatorname{\mathds{E}}(J^4)=1$, and the limiting variance reduces to the loop contribution $\sum_{n\geqslant3}\beta^{2n}/(2n)$.
	\end{enumeratea}

\label{rem:temperature-range}
	The two conditions defining $\beta_{\max}(\kappa)$ enter at different stages of the proof. a)~\textbf{The overlap condition $\beta^2<\alpha_c(\kappa)$}. This condition controls exponential moments of the overlap between uniform configurations with bounded magnetizations (Lemma~\ref{lem:profile-moments}). These bounds yield the mixed second-moment limits for the normalized partition functions and the overlap comparison. This is the only temperature restriction needed for Theorem~\ref{thm:balanced_clt}.
    b)~\textbf{The profile condition $\alpha<\alpha_c(\kappa)$}. This additional condition controls the contribution of profiles with large magnetization when removing the profile constraint. For the truncated disorder, the annealed profile weights on bounded magnetization windows are asymptotically proportional to $P_{\boldsymbol{n}}e^{\alpha\left\Vertm_{\boldsymbol{n}}\right\Vert_2^2/2}$, where $P_{\boldsymbol{n}}$ is the multinomial probability of $\boldsymbol{n}$. These leading weights are those of the Curie--Weiss--Potts model at inverse temperature $\kappa\alpha$, and $\alpha<\alpha_c(\kappa)$ places that model in its high-temperature phase~\cite{EW90}. The resulting tail bounds allow the comparison to extend to all profiles (Proposition~\ref{prop:profile-equiv}).

\label{rem:loop-motivation}
 The graph expansion of the unconstrained partition function motivates the disorder statistics used for the common factor in Step 1. Define
 \begin{align*}
  \mathrm{Ch}_\kappa(x)&:=e^{-x}\big(1+\kappa^{-1}(e^{\kappa x}-1)\big)
  \quad\text{and}\quad
  \mathrm{Th}_\kappa(x):=\frac{e^{\kappa x}-1}{e^{\kappa x}+\kappa-1}.
 \end{align*}
 The identity $e^{xA_e(\boldsymbol{\sigma})}=\mathrm{Ch}_\kappa(x)\big(1+\mathrm{Th}_\kappa(x)A_e(\boldsymbol{\sigma})\big)$ gives the exact factorization
 \begin{align*}
  Z_N(\beta;J)&=\kappa^N Z_N^{\mathrm{ch}}(\beta)Z_N^{\mathrm{cl}}(\beta),
  \quad\text{where}\\
  Z_N^{\mathrm{ch}}(\beta):=\prod_{e\in E_N}\mathrm{Ch}_\kappa(\beta J_e/\sqrt N),\quad &
  Z_N^{\mathrm{cl}}(\beta):=\operatorname{\mathds{E}}_{\boldsymbol{\sigma}}\Big(\prod_{e\in E_N}
  \big(1+ \omega_eA_e(\boldsymbol{\sigma})\big)\Big),
 \end{align*}
 where $\operatorname{\mathds{E}}_{\boldsymbol{\sigma}}$ is the uniform average on $\Sigma_N$ and $\omega_e:=\mathrm{Th}_\kappa(\beta J_e/\sqrt N)$. For $\Gamma \subseteq E_N$ write $\omega(\Gamma):=\prod_{e\in\Gamma}\omega_e$. Expanding the product yields
 \begin{align*}
  Z_N^{\mathrm{cl}}(\beta)=\sum_{\Gamma\subseteq E_N}f_\kappa(\Gamma)\omega(\Gamma),
  \quad f_\kappa(\Gamma):=\operatorname{\mathds{E}}_{\boldsymbol{\sigma}}\Big(\prod_{e\in\Gamma}A_e(\boldsymbol{\sigma})\Big).
 \end{align*}
 If $\Gamma$ has a vertex of degree one, averaging over its color gives $f_\kappa(\Gamma)=0$. For a loop $\gamma$ of length $n$, $f_\kappa(\gamma)=\operatorname{Tr}(\Pi^n)=\kappa-1$.

 To identify the leading random terms, use $\mathrm{Th}_\kappa(x)=x+\mathcal{O}(x^2)$ and replace $\omega_e$ by the centered weight $\beta J_e/\sqrt N$. For a fixed graph with $v$ nonisolated vertices and $r$ edges, the sum over its copies has variance $\mathcal{O}(N^{v-r})$, since distinct edge sets give orthogonal monomials. The contributing nonempty graphs have minimum degree at least two, so $v\leqslant r$, with equality precisely for vertex-disjoint unions of loops. Their coefficients and edge products factor over the loops, suggesting the formal approximation
 \begin{align*}
  Z_N^{\mathrm{cl}}(\beta)\approx Z_{N,\ell}^{\mathrm{loop}}(\beta)
  :=\prod_{\substack{\gamma\text{ loop}\\3\leqslant\left\vert\gamma\right\vert\leqslant\ell}}
  \big(1+(\kappa-1)\omega(\gamma)\big).
 \end{align*}
 The linear term in the formal expansion of $\ln Z_{N,\ell}^{\mathrm{loop}}$, with each $\omega_e$ replaced by $\beta J_e/\sqrt N$, gives $(\kappa-1)\sum_{n=3}^{\ell}\beta^nY_{N,n}(J)$. The expansion $\ln\mathrm{Ch}_\kappa(x)=\frac{\kappa-1}{2}x^2+\mathcal{O}(x^3)$ supplies the centered quadratic term $(\kappa-1)\beta^2X_N(J)/2$, with $X_N$ and $Y_{N,n}$ defined in~\eqref{eq:array-cycle-statistics}. After truncation, these terms give the statistic used in the proof,
 \begin{align*}
  \widetilde G_{N,\ell}
  =\frac{(\kappa-1)\beta^2}{2}\widetilde X_N
  +(\kappa-1)\sum_{n=3}^{\ell}\beta^n\widetilde Y_{N,n},
 \end{align*}
 where $\widetilde X_N$ and $\widetilde Y_{N,n}$ are defined in~\eqref{eq:truncated-loop-statistics}. At $\kappa=2$, these are the quadratic and loop terms of the cluster expansion in~\cite{ALR87}.

\label{lem:edge-id}
	For all configurations $\boldsymbol{\sigma},\boldsymbol{\tau}$ and all $x\in[\kappa]$, and with $\sigma$ uniform on $[\kappa]$ in~\eqref{eq:phi-cov},
	\begin{align}
		\phi(\sigma_i)^{\intercal}\phi(\sigma_j)=A_{ij}(\boldsymbol{\sigma}),\quad
		\left\Vert\phi(x)\right\Vert_2^2=\kappa-1,
		\label{eq:phi-prod}
	\end{align}
	\begin{align}
		\operatorname{\mathds{E}}_{\sigma}\big(\phi(\sigma)\big)=0,\quad
		\operatorname{\mathds{E}}_{\sigma}\big(\phi(\sigma)\phi(\sigma)^{\intercal}\big)=\Pi,
		\label{eq:phi-cov}
	\end{align}
	\begin{align}
		\sum_{i<j}A_{ij}(\boldsymbol{\sigma})=\frac N2\big(\left\Vertm(\boldsymbol{\sigma})\right\Vert_2^2-\kappa+1\big),
		\label{eq:vertex-edge}
	\end{align}
	\begin{align}
		\frac1N\sum_{i<j}A_{ij}(\boldsymbol{\sigma})A_{ij}(\boldsymbol{\tau})=\xi\big(\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})\big),
		\label{eq:pair-edge}
	\end{align}
	\begin{align}
		\frac{\beta^2}{2}\xi\big(\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\sigma})\big)=\frac{\beta^2(\kappa-1)}4(N-\kappa+1)
								+\frac\alpha2\left\Vertm(\boldsymbol{\sigma})\right\Vert_2^2.
		\label{eq:selfoverlap}
	\end{align}
	For three configurations,
	\begin{align}
		\frac1N\sum_{i<j}A_{ij}(\boldsymbol{\sigma})A_{ij}(\boldsymbol{\tau})A_{ij}(\boldsymbol{\tau}')
		=\frac12\big(\left\VertR^{(3)}(\boldsymbol{\sigma},\boldsymbol{\tau},\boldsymbol{\tau}')\right\Vert_F^2-(\kappa-1)^3\big).
		\label{eq:triple-edge}
	\end{align}
	If $N\geqslant2$ and $\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2,\boldsymbol{\sigma}^3$ are independent uniform configurations with profiles $\boldsymbol{n}_1,\boldsymbol{n}_2,\boldsymbol{n}_3$, then
	\begin{align}
		\operatorname{\mathds{E}}_{\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2,\boldsymbol{\sigma}^3}^{(\boldsymbol{n}_1),(\boldsymbol{n}_2),(\boldsymbol{n}_3)}\Big(
		\left\VertR^{(3)}(\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2,\boldsymbol{\sigma}^3)\right\Vert_F^2\Big)
		=(\kappa-1)^3+
		\frac{\prod_{r=1}^3\big(\left\Vertm_{\boldsymbol{n}_r}\right\Vert_2^2-\kappa+1\big)}{(N-1)^2}.
		\label{eq:triple-overlap-moment}
	\end{align}

\label{lem:Zsecond}
	Let $K_0\sim\operatorname{N}(0,\Pi\otimes\Pi)$. For $0\leqslant s<1$, $\operatorname{\mathds{E}}\big(e^{s\xi(K_0)}\big)=e^{\varphi_\kappa(s)}$. Moreover, for bounded measurable $f$ and $0<\beta^2<1$,
	\begin{align}
		e^{-\varphi_\kappa(\beta^2)}\operatorname{\mathds{E}}\big(e^{\beta^2\xi(K_0)}f(K_0)\big)=\operatorname{\mathds{E}}\left(f\Big(\frac{K_0}{\sqrt{1-\beta^2}}\Big)\right).
		\label{eq:gaussian-tilt}
	\end{align}

The Gaussian $K_0$ is standard on the range of $\Pi\otimes\Pi$, which has dimension $(\kappa-1)^2$. So $\left\VertK_0\right\Vert_F^2$ has the chi-squared law with $(\kappa-1)^2$ degrees of freedom, and its moment generating function gives
	\begin{align*}
		\operatorname{\mathds{E}}\big(e^{s\xi(K_0)}\big)=e^{-s(\kappa-1)^2/2}(1-s)^{-(\kappa-1)^2/2}=e^{\varphi_\kappa(s)}.
	\end{align*}
	Multiplying the density of $K_0$ by $e^{\beta^2\left\VertK_0\right\Vert_F^2/2}$ changes its covariance on this range from the identity to $(1-\beta^2)^{-1}$ times the identity. This gives the second assertion.

\label{lem:profile-clt}
	Fix $L>0$. Let $\boldsymbol{n}_N,\boldsymbol{n}'_N,\boldsymbol{n}''_N$ be profile sequences whose magnetizations have norm at most $L$, and let $\boldsymbol{\sigma},\boldsymbol{\tau},\boldsymbol{\tau}'$ be independent uniform configurations with these profiles. Then
	\begin{align*}
		\big(\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau}),\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau}'),\mathscr{R}(\boldsymbol{\tau},\boldsymbol{\tau}')\big)
		\Longrightarrow (K_0,K_0',K_0''),
	\end{align*}
	where $K_0,K_0',K_0''\sim\operatorname{N}(0,\Pi\otimes\Pi)$ are independent. In particular, the limit does not depend on the profiles.

\label{lem:bolthausen}
	Let $N\geqslant2$, let $(c(i,j))_{i,j=1}^{N}$ be a doubly centered real array, let $\pi$ be a uniform random permutation of $[N]$, and set $S := \sum_{i=1}^{N} c(i,\pi(i))$. Then
	\begin{align*}
		\operatorname{\mathds{E}}_\pi(S) = 0\quad\text{and}\quad v := \operatorname{Var}_\pi(S) = \frac{1}{N-1}\sum_{i,j} c(i,j)^2.
	\end{align*}
	If $v > 0$, then for an absolute constant $C$ and $\zeta \sim \operatorname{N}(0,1)$,
	\begin{align}
		\sup_{x \in \mathds{R}} \Big\lvert \operatorname{\mathds{P}}_\pi\big( S/\sqrt v \leqslant x \big) - \operatorname{\mathds{P}}\big( \zeta \leqslant x \big) \Big\rvert \leqslant \frac{C}{N v^{3/2}} \sum_{i,j} \left\vertc(i,j)\right\vert^3.
		\label{eq:comb-be}
	\end{align}

The idea is as follows. Conditionally on $\boldsymbol{\tau}$, the overlap $\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})$ is a linear statistic of a uniform permutation, to which Lemma~\ref{lem:bolthausen} applies. Its conditional variance depends on $\boldsymbol{\tau}$ only through its profile, up to a small error. For three replicas, the conditional covariance of $\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})$ and $\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau}')$ is governed by $N^{-1/2}\mathscr{R}(\boldsymbol{\tau},\boldsymbol{\tau}')\to0$, which gives asymptotic independence.

	\smallskip\noindent\textbf{Step 1 (permutation representation).} Fix a word $w$ with profile $\boldsymbol{n}_N$ and represent $\sigma_i=w_{\pi(i)}$, where $\pi$ is a uniform permutation independent of $(\boldsymbol{\tau},\boldsymbol{\tau}')$. This represents the uniform law on $\Sigma_N^{(\boldsymbol{n}_N)}$, since every configuration of that profile arises from exactly $\prod_xn_x!$ permutations. For a fixed matrix $s$,
	\begin{align*}
		\langle s,\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})\rangle_F
		=N^{-1/2}\sum_i c(i,\pi(i)),\quad
		c(i,j):=\phi(w_j)^{\intercal}s\phi(\tau_i).
	\end{align*}
	Write $c_{i\cdot},c_{\cdot j},\bar c$ for the row, column, and overall means, and define the doubly centered array
	\begin{align*}
		d(i,j):=c(i,j)-c_{i\cdot}-c_{\cdot j}+\bar c
		= \left(\phi(w_j)- \frac{m_{\boldsymbol{n}_N}}{\sqrt{N}}\right)^{\intercal}s\left(\phi(\tau_i)- \frac{m_{\boldsymbol{n}'_N}}{\sqrt{N}}\right).
	\end{align*}
	Then
	\begin{align*}
		\langle s,\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})\rangle_F
		=N^{-1/2}\sum_i \left( d(i,\pi(i)) + c_{i \cdot} + c_{\cdot \pi(i)} - \bar c \right)
		=N^{-1/2}\sum_i d(i,\pi(i)) + N^{1/2} \bar c.
	\end{align*}
	Since $N\bar c=m_{\boldsymbol{n}_N}^{\intercal}s\, m_{\boldsymbol{n}'_N}$, the last term is $\mathcal{O}(N^{-1/2})$ uniformly on the window.

	\smallskip\noindent\textbf{Step 2 (two replicas).}
	Set $a_j :=\phi(w_j)- {m_{\boldsymbol{n}_N}}/{\sqrt{N}}$ and $b_i := \phi(\tau_i)- {m_{\boldsymbol{n}'_N}}/{\sqrt{N}}$. Then
	\begin{align*}
		d(i,j)^2 = (a_j^{\intercal}sb_i)(b_i^{\intercal}s^{\intercal}a_j)
		= \operatorname{Tr}(s^{\intercal}a_ja_j^{\intercal}sb_ib_i^{\intercal}).
	\end{align*}
	It follows that
	\begin{align*}
		\frac{1}{N(N-1)}\sum_{i,j} d(i,j)^2 = \frac{N}{N-1} \operatorname{Tr} \left[ s^{\intercal}\left(\frac{1}{N} \sum_j a_j a_j^{\intercal}\right)s\left(\frac{1}{N} \sum_i b_i b_i^{\intercal}\right)\right].
	\end{align*}
	Let $p = \boldsymbol{n}_N / N$. Using $p = u + (\kappa N)^{-1/2}m_{\boldsymbol{n}_N}$ and $m_{\boldsymbol{n}_N} = \mathcal{O}(1)$, we get
	\begin{align*}
		\frac{1}{N} \sum_j a_j a_j^{\intercal} = \sum_{x=1}^\kappa p_x \phi(x) \phi(x)^{\intercal} - \frac{1}{N} m_{\boldsymbol{n}_N} m_{\boldsymbol{n}_N}^{\intercal}
		\to \Pi.
	\end{align*}
	The same approximation applies to $b_i$, and we obtain the limit of the conditional variance:
	\begin{align*}
		\operatorname{Var}\Big( N^{-1/2}\sum_i d(i,\pi(i)) \,\Big|\, \boldsymbol{\tau} \Big)=\frac1{N(N-1)}\sum_{i,j}d(i,j)^2
		\longrightarrow \operatorname{Tr}(s^{\intercal}\Pi s\Pi)=\left\Vert\Pi s\Pi\right\Vert_F^2.
	\end{align*}
	This limit is deterministic, since it depends on $\boldsymbol{\tau}$ only through its profile. The arrays are uniformly bounded. If the limiting variance is positive, we apply Lemma~\ref{lem:bolthausen} to the array $d(i,j)/\sqrt N$. Since $\sum_{i,j}\left\vertd(i,j)\right\vert^3=\mathcal{O}(N^2)$, the bound~\eqref{eq:comb-be} is $\mathcal{O}(N^{-1/2})$. If the limiting variance is zero, Chebyshev's inequality applies. Since $\left\Vert\Pi s\Pi\right\Vert_F^2=\operatorname{Var}(\langle s,K_0\rangle_F)$, the Cram\'er--Wold device proves the two-replica assertion, uniformly along profile sequences in the window.

	\smallskip\noindent\textbf{Step 3 (three replicas).} Fix matrices $s_1,s_2,s_3$ and write
	\begin{align*}
		T_1:=\langle s_1,\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})\rangle_F,\quad
		T_2:=\langle s_2,\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau}')\rangle_F,\quad
		T_3:=\langle s_3,\mathscr{R}(\boldsymbol{\tau},\boldsymbol{\tau}')\rangle_F.
	\end{align*}
	Conditionally on $(\boldsymbol{\tau},\boldsymbol{\tau}')$, $T_1+T_2$ is a single permutation statistic:
	\begin{align*}
		T_1 + T_2
		=N^{-1/2}\sum_i c'(i,\pi(i)),
		\quad c'(i,j):=\phi(w_j)^{\intercal}\big(s_1\phi(\tau_i)+s_2\phi(\tau'_i)\big).
	\end{align*}
	As in Steps 1 and 2, define the doubly centered array
	\begin{align*}
		d'(i,j):=c'(i,j)-c'_{i\cdot}-c'_{\cdot j}+\bar c'
		= \left(\phi(w_j)- \frac{m_{\boldsymbol{n}_N}}{\sqrt{N}}\right)^{\intercal} \left[s_1\left(\phi(\tau_i)- \frac{m_{\boldsymbol{n}'_N}}{\sqrt{N}}\right) + s_2\left(\phi(\tau'_i)- \frac{m_{\boldsymbol{n}''_N}}{\sqrt{N}}\right)\right].
	\end{align*}
	Then
	\begin{align*}
		T_1 + T_2
		=N^{-1/2}\sum_i d'(i,\pi(i)) + \mathcal{O}(N^{-1/2}).
	\end{align*}
	Recall $a_j$ and $b_i$ from Step 2 and set $b_i' := \phi(\tau_i')- {m_{\boldsymbol{n}''_N}}/{\sqrt{N}}$. Then
	\begin{align*}
		d'(i,j)^2
		= \operatorname{Tr}(s_1^{\intercal}a_ja_j^{\intercal}s_1b_ib_i^{\intercal})
		+\operatorname{Tr}(s_2^{\intercal}a_ja_j^{\intercal}s_2b_i'(b_i')^{\intercal})
		+2\operatorname{Tr}(s_2^{\intercal}a_ja_j^{\intercal}s_1b_i(b_i')^{\intercal}).
	\end{align*}
	Moreover, $N^{-1}\sum_i b_i (b_i')^{\intercal} =N^{-1/2}\mathscr{R}(\boldsymbol{\tau},\boldsymbol{\tau}')+ \mathcal{O}(1/N)$, which tends to zero in probability by the two-replica assertion. Hence
	\begin{align*}
		\operatorname{Var} \big(T_1 + T_2 \,\big|\, \boldsymbol{\tau}, \boldsymbol{\tau}' \big) \longrightarrow \left\Vert\Pi s_1\Pi\right\Vert_F^2 + \left\Vert\Pi s_2\Pi\right\Vert_F^2\quad\text{in probability}.
	\end{align*}
	If this limit is positive, Lemma~\ref{lem:bolthausen} applies on an event where the conditional variance is bounded below, and the complement of this event has probability tending to zero. The conditional characteristic function of $T_1+T_2$ therefore converges in probability, and in $L^1$ by boundedness, to the deterministic Gaussian characteristic function. If the limit vanishes, the same conclusion follows from the conditional second moment. Since $T_3$ is measurable with respect to $(\boldsymbol{\tau},\boldsymbol{\tau}')$,
	\begin{align*}
		\operatorname{\mathds{E}}\big(e^{\mathrm{i}(T_1+T_2+T_3)}\big)
		=\operatorname{\mathds{E}}\Big(e^{\mathrm{i} T_3}\,\operatorname{\mathds{E}}\big(e^{\mathrm{i}(T_1+T_2)}\,\big|\,\boldsymbol{\tau},\boldsymbol{\tau}'\big)\Big),
	\end{align*}
	and this factorizes in the limit into the product of the two limiting Gaussian characteristic functions. The two-replica result for $T_3$ and the Cram\'er--Wold device complete the proof.

\label{lem:profile-types}
	Let $p=\boldsymbol{n}/N$ and $p'=\boldsymbol{n}'/N$. Every realizable pair type $q$ has margins $(q^{(1)},q^{(2)})=(p,p')$, and
	\begin{align}
		\operatorname{\mathds{P}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}
			\big(p(\boldsymbol{\sigma},\boldsymbol{\tau})=q\big)
		&=\frac{\prod_y\binom{n'_y}{(Nq_{xy})_x}}{\binom N{(n_x)_x}}
		\leqslant(N+1)^\kappa e^{-ND(q\|p\otimes p')}.
		\label{eq:profile-types}
	\end{align}
	On the \emph{core} $\{q:q_{xy}\geqslant1/(2\kappa^2)\text{ for all }x,y\}$ the sharper bound
	\begin{align}
		\operatorname{\mathds{P}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}
			\big(p(\boldsymbol{\sigma},\boldsymbol{\tau})=q\big)
		\leqslant C N^{-(\kappa-1)^2/2}e^{-ND(q\|p\otimes p')}
		\label{eq:profile-types-sharp}
	\end{align}
	holds.

Fix $\boldsymbol{\tau}$. The configurations $\boldsymbol{\sigma}\in\Sigma_N^{(\boldsymbol{n})}$ with pair type $q$ are obtained by choosing, within each color class $\{i:\tau_i=y\}$ of $\boldsymbol{\tau}$, which sites receive each color of $\boldsymbol{\sigma}$, with prescribed counts $(Nq_{xy})_x$. Dividing this count by $\left\vert\Sigma_N^{(\boldsymbol{n})}\right\vert=\binom N{(n_x)_x}$ gives the exact ratio. Write $\mathcal{S}(p):=-\sum_xp_x\ln p_x$. The multinomial bounds of the method of types~\cite[Lemma 2.1.8]{DZ98},
	\begin{align*}
		(n+1)^{-\kappa}e^{n\mathcal{S}(a/n)}\leqslant\binom n{(a_x)_x}\leqslant e^{n\mathcal{S}(a/n)},
	\end{align*}
	and the identity
	\begin{align}
		\sum_y n'_y\mathcal{S}((Nq_{xy}/n'_y)_x)-N\mathcal{S}(p)
		&=-N\sum_y p'_y\sum_x\frac{q_{xy}}{p'_y}\ln\frac{q_{xy}}{p'_y}
		+N\sum_{x,y}q_{xy}\ln p_x\nonumber\\
		&=-ND(q\|p\otimes p')
		\label{eq:profile-type-entropy}
	\end{align}
	prove~\eqref{eq:profile-types}.
	On the core, each $Nq_{xy}$ is a positive integer. Stirling's bounds
	\begin{align*}
		\sqrt{2\pi n}\,(n/e)^n\leqslant n!\leqslant\sqrt{2\pi n}\,(n/e)^n e^{1/(12n)}
	\end{align*}
	yield
	\begin{align*}
		\binom{n'_y}{(Nq_{xy})_x}
		&\leqslant e^{1/12}(2\pi)^{-(\kappa-1)/2}(n'_y)^{-(\kappa-1)/2}
		\left(\prod_x\frac{Nq_{xy}}{n'_y}\right)^{-1/2}
		e^{n'_y\mathcal{S}((Nq_{xy}/n'_y)_x)}\\
		&\leqslant C N^{-(\kappa-1)/2}e^{n'_y\mathcal{S}((Nq_{xy}/n'_y)_x)}.
	\end{align*}
	Here we used $Nq_{xy}/n'_y\geqslant q_{xy}\geqslant1/(2\kappa^2)$ and $n'_y=N\sum_xq_{xy}\geqslant N/(2\kappa)$ on the core. The same computation, with the two Stirling bounds interchanged, bounds the denominator in~\eqref{eq:profile-types} from below:
	\begin{align*}
		\binom N{(n_x)_x}\geqslant cN^{-(\kappa-1)/2}e^{N\mathcal{S}(p)}.
	\end{align*}
	Combining these bounds with the entropy identity~\eqref{eq:profile-type-entropy} proves~\eqref{eq:profile-types-sharp}.

\label{lem:near-uniform}
	Let $q$ be a probability measure on $[\kappa]^2$ with margins $(p,p')$. Define $w := q - p\otimes p'$ and $\delta := \left\Vertp-u\right\Vert_\infty \vee \left\Vertp'-u\right\Vert_\infty$. There is $C = C(\kappa)$ such that, if $\kappa\delta \leqslant \tfrac12$, then
	\begin{align}
		D\big(q  \|  p \otimes p'\big)  \geqslant \frac{\alpha_c(\kappa) \kappa^2}{2}  \left\Vertw\right\Vert_F^2  -  C\big( \delta \left\Vertw\right\Vert_F + \delta^2 \big).
		\label{eq:near-uniform}
	\end{align}

\label{lem:profile-moments}
	Let $0<\beta^2<\alpha_c(\kappa)$ and $L>0$. Then
	\begin{enumeratei}
		\item
		\begin{align*}
			\sup_N\sup_{\left\Vertm_{\boldsymbol{n}}\right\Vert_2,\left\Vertm_{\boldsymbol{n}'}\right\Vert_2\leqslant L}
			\operatorname{\mathds{E}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}\big(e^{\beta^2\xi(\mathscr{R})}\big)
			<\infty,
		\end{align*}
		\item
		\begin{align*}
			\sup_{\left\Vertm_{\boldsymbol{n}}\right\Vert_2,\left\Vertm_{\boldsymbol{n}'}\right\Vert_2\leqslant L}
			\left|\operatorname{\mathds{E}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}\big(e^{\beta^2\xi(\mathscr{R})}\big)-e^{\varphi_\kappa(\beta^2)}\right|\to0.
		\end{align*}
	\end{enumeratei}
	Here $\mathscr{R}=\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})$.

Write $p=\boldsymbol{n}/N$ and $p'=\boldsymbol{n}'/N$, and let $\mathcal{T}_N$ be the set of realizable pair types with these margins. Conditioning on the pair type and using $\mathscr{R}=\kappa\sqrt N\hat q$ in the definition of $\xi$, we obtain the type expansion
	\begin{align*}
		\operatorname{\mathds{E}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}\big(e^{\beta^2\xi(\mathscr{R})}\big)
		=e^{-\frac{\beta^2}2(\kappa-1)^2}
		\sum_{q\in\mathcal{T}_N}\operatorname{\mathds{P}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}
		\big(p(\boldsymbol{\sigma},\boldsymbol{\tau})=q\big)
		e^{\frac{\beta^2\kappa^2N}{2}\left\Vert\hat q\right\Vert_F^2}.
	\end{align*}

	(i) \smallskip\noindent\textbf{Step 1 (energy and entropy).} Define $w=q-p\otimes p'$ and $\delta=\left\Vertp-u\right\Vert_\infty\vee\left\Vertp'-u\right\Vert_\infty\leqslant L/\sqrt{\kappa N}$. Since $w$ is doubly centered and $\Pi p=p-u$,
	\begin{align*}
		\hat q-w=\Pi(p\otimes p')\Pi=(p-u)(p'-u)^{\intercal}
		\quad\text{and}\quad
		\left\Vert\hat q-w\right\Vert_F\leqslant\kappa\delta^2.
	\end{align*}
	The resulting energy error is controlled by
	\begin{align*}
		\left\Vert\hat q\right\Vert_F^2-\left\Vertw\right\Vert_F^2
		=2\langle\hat q-w,w\rangle_F+\left\Vert\hat q-w\right\Vert_F^2
		\leqslant2\kappa\delta^2\left\Vertw\right\Vert_F+\kappa^2\delta^4.
	\end{align*}
	Set $a:=(\alpha_c(\kappa)-\beta^2)\kappa^2/2>0$. Combining this estimate with Lemma~\ref{lem:near-uniform} and using $\delta\leqslant L/\sqrt{\kappa N}$, we get, for $N\geqslant C(1+L^2)$,
	\begin{align*}
		\frac{\beta^2\kappa^2N}{2}\left\Vert\hat q\right\Vert_F^2-ND(q\|p\otimes p')
		\leqslant-Na\left\Vertw\right\Vert_F^2+C\sqrt N L\left\Vertw\right\Vert_F+CL^2.
	\end{align*}
	Completing the square,
	\begin{align*}
		-\frac{Na}{2}\left\Vertw\right\Vert_F^2+C\sqrt N L\left\Vertw\right\Vert_F
		=-\frac{Na}{2}\left(\left\Vertw\right\Vert_F-\frac{CL}{a\sqrt N}\right)^2
		+\frac{C^2L^2}{2a}
		\leqslant CL^2.
	\end{align*}
	Consequently,
	\begin{align}
		\frac{\beta^2\kappa^2N}{2}\left\Vert\hat q\right\Vert_F^2-ND(q\|p\otimes p')
		\leqslant-\frac{Na}{2}\left\Vertw\right\Vert_F^2+CL^2.
		\label{eq:profile-exponent}
	\end{align}

	\smallskip\noindent\textbf{Step 2 (lattice sum over core types).} A table with fixed margins is determined by its entries with $x,y<\kappa$. Each $Nq_{xy}$ is an integer, and $\left\Vertw\right\Vert_F^2\geqslant\sum_{x,y<\kappa}(q_{xy}-p_xp'_y)^2$. Thus~\eqref{eq:profile-types-sharp} and~\eqref{eq:profile-exponent} give
	\begin{align*}
		\sum_{q\text{ core}}\operatorname{\mathds{P}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}
		\big(p(\boldsymbol{\sigma},\boldsymbol{\tau})=q\big)e^{\frac{\beta^2\kappa^2N}{2}\left\Vert\hat q\right\Vert_F^2}
		&\leqslant C e^{CL^2}N^{-(\kappa-1)^2/2}
		\sum_{q\in\mathcal{T}_N}e^{-\frac{Na}2\left\Vertq-p\otimes p'\right\Vert_F^2}\\
		&\leqslant C e^{CL^2}N^{-(\kappa-1)^2/2}
		\prod_{x,y<\kappa}\left(\sum_{j\in\mathds{Z}}e^{-\frac a{2N}(j-Np_xp'_y)^2}\right)
		\leqslant Ce^{CL^2}.
	\end{align*}
	For the last inequality, the one-dimensional Gaussian sum satisfies
	\begin{align*}
		\sup_{b\in\mathds{R}}\sum_{j\in\mathds{Z}}e^{-\frac a{2N}(j-b)^2}
		\leqslant2+\sqrt{\frac{2\pi N}{a}}\leqslant C\sqrt N.
	\end{align*}
	There are $(\kappa-1)^2$ such factors, so their powers of $N$ cancel the prefactor, uniformly over the profiles.

	\smallskip\noindent\textbf{Step 3 (remaining types).} If $q$ is not in the core, some cell has $q_{xy}<1/(2\kappa^2)$. Since $p$ and $p'$ tend to $u$ uniformly on the profile window, $\left\Vertq-p\otimes p'\right\Vert_F\geqslant1/(4\kappa^2)$ for $N\geqslant C(1+L^2)$, after increasing $C$ if necessary. There are at most $(N+1)^{\kappa^2}$ types. So~\eqref{eq:profile-types} and Step 1 imply
	\begin{align*}
		\sum_{q\text{ not core}}\operatorname{\mathds{P}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}
		\big(p(\boldsymbol{\sigma},\boldsymbol{\tau})=q\big)e^{\frac{\beta^2\kappa^2N}{2}\left\Vert\hat q\right\Vert_F^2}
		\leqslant e^{CL^2}(N+1)^{\kappa+\kappa^2}
		e^{-Na/(32\kappa^4)}\longrightarrow0,
	\end{align*}
	uniformly over the profiles. In particular, this sum is bounded by $C$ uniformly in $N$. For fixed $L$, the finitely many smaller $N$ also give finite expectations, since their configuration spaces are finite. Thus Steps 2 and 3 prove (i).

	(ii) Choose $\beta^2<s<\alpha_c(\kappa)$. Part (i) with $\beta^2$ replaced by $s$ bounds the expectation of $\big(e^{\beta^2\xi(\mathscr{R})}\big)^{s/\beta^2}=e^{s\xi(\mathscr{R})}$ uniformly over $N$ and the profile window. Hence these exponential weights are uniformly integrable. By Lemma~\ref{lem:profile-clt}, $\mathscr{R}\Longrightarrow K_0$ along every sequence of profiles in the window. The continuous mapping theorem, uniform integrability, and Lemma~\ref{lem:Zsecond} therefore give
	\begin{align*}
		\operatorname{\mathds{E}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}\big(e^{\beta^2\xi(\mathscr{R})}\big)
		\longrightarrow\operatorname{\mathds{E}}\big(e^{\beta^2\xi(K_0)}\big)
		=e^{-\frac{\beta^2}2(\kappa-1)^2}(1-\beta^2)^{-(\kappa-1)^2/2}
		=e^{\varphi_\kappa(\beta^2)}.
	\end{align*}
	If the uniform convergence in (ii) failed, some sequence of profile pairs in the window would have errors bounded below by a fixed positive number along a subsequence. This contradicts the convergence just proved.

\label{rem:overlap-threshold}
	For $\kappa\geqslant3$, the entropy bound for uniform margins is attained by the pair measure
	\begin{align*}
		q^*_{xx}=\frac{\kappa-1}{\kappa^2},\qquad
		q^*_{xy}=\frac1{\kappa^2(\kappa-1)}\quad(y\ne x).
	\end{align*}
	Each row is $\kappa^{-1}$ times a permutation of $p^*$ from Lemma~\ref{lem:eta-phi}, with its large entry on the diagonal. Thus $q^*$ has uniform margins and
	\begin{align*}
		D(q^*\|\bar u)=\frac{\alpha_c(\kappa)\kappa^2}{2}\left\Vertq^*-\bar u\right\Vert_F^2.
	\end{align*}
	Along $N$ divisible by $\kappa^2(\kappa-1)$, the measure $q^*$ is a realizable pair type for two balanced configurations. The exact probability in~\eqref{eq:profile-types} and Stirling's formula give
	\begin{align*}
		\ln\operatorname{\mathds{P}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}^*),(\boldsymbol{n}^*)}\big(p(\boldsymbol{\sigma},\boldsymbol{\tau})=q^*\big)
		=-ND(q^*\|\bar u)+\mathcal{O}(\ln N).
	\end{align*}
	Consequently, this single type gives the lower bound
	\begin{align*}
		\operatorname{\mathds{E}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}^*),(\boldsymbol{n}^*)}\big(e^{\beta^2\xi(\mathscr{R})}\big)
		\geqslant\exp\left\{\frac{N(\beta^2-\alpha_c(\kappa))\kappa^2}{2}\left\Vertq^*-\bar u\right\Vert_F^2-C\ln N\right\}.
	\end{align*}
	For $\beta^2>\alpha_c(\kappa)$ this diverges exponentially along the indicated sequence of $N$, so the uniform bound in Lemma~\ref{lem:profile-moments}(i) fails above this threshold. The same conclusion holds for the second moment of the normalized balanced partition function under the truncated disorder: the one-edge expansion~\eqref{eq:general-edge-cumulant} shows that it differs from this overlap exponential moment by factors bounded above and below by positive constants, for each fixed $\beta$.

\label{lem:general-kernels}
	For fixed $0<\beta^2<1$, uniformly over configurations,
	\begin{align}
		c_N(\boldsymbol{\sigma})
		&=\frac{\beta^2(\kappa-1)}4(N-\kappa+1)+\frac\alpha2\left\Vertm(\boldsymbol{\sigma})\right\Vert_2^2
			+\frac{\mu_4\beta^4(\kappa-1)(\kappa^2-3\kappa+3)}{48}
			+\mathfrak{R}_N^{(1)}(\boldsymbol{\sigma}),
		\label{eq:general-self-kernel}\\
		\Lambda_N(\boldsymbol{\sigma},\boldsymbol{\tau})
		&=\beta^2\xi\big(\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})\big)+\varphi_{\kappa,J}(\beta^2)-\varphi_{\kappa}(\beta^2)
		+\mathfrak{R}_N^{(2)}(\boldsymbol{\sigma},\boldsymbol{\tau}),
		\label{eq:general-pair-kernel}\\
		\Lambda^{(3)}_N(\boldsymbol{\sigma},\boldsymbol{\tau},\boldsymbol{\tau}')
		&=\Lambda_N(\boldsymbol{\sigma},\boldsymbol{\tau})+\Lambda_N(\boldsymbol{\sigma},\boldsymbol{\tau}')
			+\Lambda_N(\boldsymbol{\tau},\boldsymbol{\tau}')+\mathfrak{R}_N^{(3)}(\boldsymbol{\sigma},\boldsymbol{\tau},\boldsymbol{\tau}'),
		\label{eq:general-triple-kernel}
	\end{align}
	where
	\begin{align*}
		\left\vert\mathfrak{R}_N^{(1)}(\boldsymbol{\sigma})\right\vert
		\leqslant o(1)+\frac CN\left\Vertm(\boldsymbol{\sigma})\right\Vert_2^2.
	\end{align*}
	The remainders $\mathfrak{R}_N^{(2)}$ and $\mathfrak{R}_N^{(3)}$ are bounded uniformly in $N$ and in the configurations. Under independent uniform configurations with profiles in a fixed window $\left\Vertm_{\boldsymbol{n}}\right\Vert_2\leqslant L$, both converge to zero in probability, uniformly over the profiles. Explicitly, for every fixed $L>0$ and $\varepsilon>0$,
	\begin{align*}
		\sup_{\left\Vertm_{\boldsymbol{n}}\right\Vert_2,\left\Vertm_{\boldsymbol{n}'}\right\Vert_2\leqslant L}
		\operatorname{\mathds{P}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}
		\big(\left\vert\mathfrak{R}_N^{(2)}(\boldsymbol{\sigma},\boldsymbol{\tau})\right\vert>\varepsilon\big)\to0,
	\end{align*}
	and the analogous statement holds for $\mathfrak{R}_N^{(3)}$, with the supremum over three profiles in the same window.

\emph{The one-edge expansion.} Fix $C>0$. Since $\widetilde{J}$ is symmetric and $\left\vertz\widetilde{J}\right\vert\leqslant C\varepsilon_N$ for $\left\vertz\right\vert\leqslant C/\sqrt N$, Taylor's formula gives, uniformly on this interval,
	\begin{align*}
		\operatorname{\mathds{E}}\big(e^{z\widetilde{J}}\big) =1+\frac{z^2}{2}\operatorname{\mathds{E}}\big(\widetilde{J}^2\big)+\frac{z^4}{24}\operatorname{\mathds{E}}\big(\widetilde{J}^4\big) +\mathcal{O}\big(\left\vertz\right\vert^6\operatorname{\mathds{E}}(\left\vert\widetilde{J}\right\vert^6)\big).
	\end{align*}
	Here $\operatorname{\mathds{E}}(\left\vert\widetilde{J}\right\vert^6)\leqslant\varepsilon_N^2N\operatorname{\mathds{E}}(J^4)=o(N)$, so the remainder is $o(N^{-2})$. The moment estimates~\eqref{eq:truncated-second-moment} and~\eqref{eq:truncated-fourth-moment} therefore yield
	\begin{align*}
		\operatorname{\mathds{E}}\big(e^{z\widetilde{J}}\big)=1+\frac{z^2}{2}+\frac{z^4}{24}\operatorname{\mathds{E}}\big(J^4\big)+o(N^{-2}).
	\end{align*}
	The terms after $1$ are $\mathcal{O}(N^{-1})$. Applying $\ln(1+x)=x-x^2/2+\mathcal{O}(x^3)$ and recalling $\mu_4=\operatorname{\mathds{E}}(J^4)-3$ gives
	\begin{align}
		\ln\operatorname{\mathds{E}}\big(e^{z\widetilde{J}}\big)=\frac{z^2}{2}+\frac{\mu_4z^4}{24}+o(N^{-2}),
		\quad\left\vertz\right\vert\leqslant C/\sqrt N.
		\label{eq:general-edge-cumulant}
	\end{align}
	All errors are uniform in $z$. Since the edge weights are bounded, we may sum this expansion over the $\binom N2$ edges, for one configuration or for any fixed sum of configurations, with a uniform $o(1)$ error.

	\emph{One configuration.} The two possible values $-1$ and $\kappa-1$ of $A_e$ give
	\begin{align*}
		A_e^2=(\kappa-2)A_e+\kappa-1
		\quad\text{and}\quad
		A_e^4=(\kappa-2)(\kappa^2-2\kappa+2)A_e
			+(\kappa-1)(\kappa^2-3\kappa+3).
	\end{align*}
	By~\eqref{eq:general-edge-cumulant},
	\begin{align*}
		c_N(\boldsymbol{\sigma})
		= \sum_{e} \ln \operatorname{\mathds{E}}\big( e^{\beta N^{-1/2} A_e (\boldsymbol{\sigma}) \widetilde J_e}\big)
		=\frac{\beta^2}{2N}\sum_e A_e(\boldsymbol{\sigma})^2
		+\frac{\mu_4\beta^4}{24N^2}\sum_e A_e(\boldsymbol{\sigma})^4+o(1).
	\end{align*}
	By~\eqref{eq:pair-edge} and~\eqref{eq:selfoverlap}, the quadratic term equals the first two terms of~\eqref{eq:general-self-kernel}. The constant part of the quartic term is
	\begin{align*}
		\frac{\mu_4\beta^4(\kappa-1)(\kappa^2-3\kappa+3)}{24N^2}\binom N2
		=\frac{\mu_4\beta^4(\kappa-1)(\kappa^2-3\kappa+3)}{48}+\mathcal{O}(N^{-1}).
	\end{align*}
	By~\eqref{eq:vertex-edge}, its remaining part is bounded by $CN^{-1}(1+\left\Vertm(\boldsymbol{\sigma})\right\Vert_2^2)$. This proves~\eqref{eq:general-self-kernel} and the bound on $\mathfrak{R}_N^{(1)}$.

	\emph{Two configurations.} In this proof write $a_e=A_e(\boldsymbol{\sigma})$ and $a'_e=A_e(\boldsymbol{\tau})$. Independence of the edges and~\eqref{eq:general-edge-cumulant} give
	\begin{align*}
		\Lambda_N(\boldsymbol{\sigma},\boldsymbol{\tau})
		=\frac{\beta^2}{N}\sum_e a_ea'_e +\frac{\mu_4\beta^4}{24N^2}
		\sum_e\big(4a_e^3a'_e+6a_e^2(a'_e)^2+4a_e(a'_e)^3\big)+o(1).
	\end{align*}
	The quadratic term equals $\beta^2\xi\big(\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})\big)$ by~\eqref{eq:pair-edge}. For the quartic term,
	\begin{align*}
		a_e^3a'_e&=(\kappa^2-3\kappa+3)a_ea'_e
			+(\kappa-1)(\kappa-2)a'_e,\\
		a_e^2(a'_e)^2&=(\kappa-2)^2a_ea'_e
			+(\kappa-1)(\kappa-2)(a_e+a'_e)+(\kappa-1)^2.
	\end{align*}
	Thus only $6a_e^2(a'_e)^2$ supplies a constant term, and its contribution is
	\begin{align*}
		\frac{\mu_4\beta^4}{24N^2}\,6(\kappa-1)^2\binom N2
		=\varphi_{\kappa,J}(\beta^2)-\varphi_\kappa(\beta^2)+\mathcal{O}(N^{-1}).
	\end{align*}
	All other quartic terms are linear combinations of $\sum_e a_e$, $\sum_e a'_e$, and $\sum_e a_ea'_e$. By~\eqref{eq:vertex-edge}--\eqref{eq:pair-edge} and the definition of $\xi$, and after absorbing the configuration-independent $\mathcal{O}(N^{-1})$ terms into $o(1)$,
	\begin{align*}
		\left\vert\mathfrak{R}_N^{(2)}(\boldsymbol{\sigma},\boldsymbol{\tau})\right\vert
		\leqslant o(1)+\frac CN\big(\left\Vertm(\boldsymbol{\sigma})\right\Vert_2^2+\left\Vertm(\boldsymbol{\tau})\right\Vert_2^2
									+\left\Vert\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})\right\Vert_F^2\big).
	\end{align*}
	This proves~\eqref{eq:general-pair-kernel} with the displayed remainder bound. Since $\left\Vertm\right\Vert_2^2\leqslant N(\kappa-1)$ and $\left\Vert\mathscr{R}\right\Vert_F^2\leqslant N(\kappa-1)^2$, the remainder is uniformly bounded. On a fixed profile window, Lemma~\ref{lem:profile-clt} gives $\left\Vert\mathscr{R}\right\Vert_F^2=\mathcal{O}_{\operatorname{\mathds{P}}}(1)$ uniformly, so $\mathfrak{R}_N^{(2)}\to0$ in probability, uniformly over the profiles.

	\emph{Three configurations.} Define $a''_e=A_e(\boldsymbol{\tau}')$. Subtracting the three pair kernels from the logarithm of the triple moment cancels the quadratic terms. The surviving quartic terms in~\eqref{eq:general-edge-cumulant} give
	\begin{align*}
		\mathfrak{R}_N^{(3)}(\boldsymbol{\sigma},\boldsymbol{\tau},\boldsymbol{\tau}')
		=\frac{\mu_4\beta^4}{2N^2}\sum_e
		\big(a_e^2a'_ea''_e+a_e(a'_e)^2a''_e+a_ea'_e(a''_e)^2\big)+o(1).
	\end{align*}
	This is uniformly bounded, since each edge weight is bounded. To prove convergence to zero, we use
	\begin{align*}
		a_e^2a'_ea''_e+a_e(a'_e)^2a''_e+a_ea'_e(a''_e)^2
		=3(\kappa-2)a_ea'_ea''_e+(\kappa-1)(a_ea'_e+a_ea''_e+a'_ea''_e).
	\end{align*}
	The identities~\eqref{eq:pair-edge} and~\eqref{eq:triple-edge} now yield
	\begin{align*}
		\mathfrak{R}_N^{(3)}(\boldsymbol{\sigma},\boldsymbol{\tau},\boldsymbol{\tau}')
		&=\frac{\mu_4\beta^4}{2N}\Big[
		\frac{3(\kappa-2)}2\big(\left\VertR^{(3)}(\boldsymbol{\sigma},\boldsymbol{\tau},\boldsymbol{\tau}')\right\Vert_F^2-(\kappa-1)^3\big)\\
		&\quad+(\kappa-1)\big(\xi\big(\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})\big)+\xi\big(\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau}')\big)
		+\xi\big(\mathscr{R}(\boldsymbol{\tau},\boldsymbol{\tau}')\big)\big)\Big]+o(1).
	\end{align*}
	Under independent uniform configurations in a fixed profile window, the expectation in~\eqref{eq:triple-overlap-moment} is uniformly bounded. Markov's inequality gives $\left\VertR^{(3)}\right\Vert_F^2=\mathcal{O}_{\operatorname{\mathds{P}}}(1)$ uniformly over these profiles, and Lemma~\ref{lem:profile-clt} gives the same bound for the three pair overlaps. The displayed expression therefore tends to zero in probability, uniformly over the profiles.

\label{lem:general-profile-moments}
	For $0<\beta^2<\alpha_c(\kappa)$ and $L>0$,
	\begin{align}
		\sup_{\left\Vertm_{\boldsymbol{n}}\right\Vert_2,\left\Vertm_{\boldsymbol{n}'}\right\Vert_2\leqslant L}
		\left\vert\operatorname{\mathds{E}}\big( \mathcal{Z}_N^{(\boldsymbol{n})} \mathcal{Z}_N^{(\boldsymbol{n}')}\big)
						-e^{\varphi_{\kappa,J}(\beta^2)}\right\vert&\to0,
		\label{eq:general-mixed-second}\\
		\sup_{\left\Vertm_{\boldsymbol{n}}\right\Vert_2\leqslant L}
		\operatorname{\mathds{E}}\Big(\big( \mathcal{Z}_N^{(\boldsymbol{n})}- \mathcal{Z}_N^{(\boldsymbol{n}^*)}\big)^2\Big)&\to0.
		\label{eq:general-profile-collapse}
	\end{align}

\label{prop:array-joint-clt}
	Suppose that the edges $\mathcal{J}_{N,e}$ are independent and centered, and that
	\begin{align}
		\max_{e\in E_N}\left\vert\operatorname{\mathds{E}}(\mathcal{J}_{N,e}^2)-1\right\vert\to0
		\quad\text{and}\quad
		\frac1{N^2}\sum_{e\in E_N}\operatorname{Var}(\mathcal{J}_{N,e}^2)\to v\in[0,\infty).
		\label{eq:array-moment-limits}
	\end{align}
	Assume also that their fourth powers are uniformly integrable:
	\begin{align}
		\lim_{M\to\infty}\sup_{N,e}\operatorname{\mathds{E}}\big(\mathcal{J}_{N,e}^4\mathds{1}\{\left\vert\mathcal{J}_{N,e}\right\vert\geqslant M\}\big)=0.
		\label{eq:array-fourth-integrability}
	\end{align}
	Then, for fixed $\ell\geqslant3$,
	\begin{align*}
		\big(X_N(\mathcal{J}_N),Y_{N,3}(\mathcal{J}_N),\ldots,Y_{N,\ell}(\mathcal{J}_N)\big)
		\Longrightarrow \operatorname{N}(0,v)\otimes\bigotimes_{n=3}^{\ell}\operatorname{N}\left(0,\frac1{2n}\right).
	\end{align*}

\label{lem:DP}
	Fix $r \geqslant 2$ and integers $p_1, \ldots, p_r \geqslant 1$, and let $n_m \to \infty$. For each $m$, let $F_m = (F_m(1), \ldots, F_m(r))$ be a vector of centered, unit-variance random variables in $L^4$, built from independent random elements $X^{(m)}_1, \ldots, X^{(m)}_{n_m}$. Assume that each $F_m(k)$ is a degenerate $U$-statistic of order $p_k$, with Hoeffding decomposition $F_m(k) = \sum_{\left\vert\mathcal{I}\right\vert=p_k} F_{m,\mathcal{I}}(k)$. Define the maximal influence of the $k$-th coordinate by
	\begin{align*}
		\mathrm{Infl}_k(F_m) := \max_{1 \leqslant j \leqslant n_m} \sum_{\left\vert\mathcal{I}\right\vert = p_k,\, \mathcal{I} \ni j} \operatorname{Var}\big(F_{m,\mathcal{I}}(k)\big).
	\end{align*}
	Let $\Sigma \in \mathds{R}^{r \times r}$ be positive semi-definite with $\Sigma(k,k) = 1$ for every $k$, and let $\boldsymbol{g} = (\boldsymbol{g}(1), \ldots, \boldsymbol{g}(r)) \sim \operatorname{N}_r(0,\Sigma)$. Assume that, as $m \to \infty$,
	\begin{enumeratei}
	\item the covariance matrix of $F_m$ converges to $\Sigma$,
	\item $\mathrm{Infl}_k(F_m) \to 0$ for every $k$,
	\item $\operatorname{\mathds{E}}\big(F_m(k)^4\big) \to 3$ for every $k$, and
	\item $\operatorname{\mathds{E}}\big(F_m(j)^2 F_m(k)^2\big) \to \operatorname{\mathds{E}}\big(\boldsymbol{g}(j)^2 \boldsymbol{g}(k)^2\big)$ whenever $j \neq k$ and $p_j = p_k$.
	\end{enumeratei}
	Then $F_m \Longrightarrow \boldsymbol{g}$.

\label{lem:loop-chaos}
	Assume the hypotheses of Proposition~\ref{prop:array-joint-clt}, and fix $3\leqslant n,n'\leqslant\ell$.
	\begin{enumeratei}
		\item The loop statistics are centered, and distinct lengths are orthogonal:
		\begin{align}
			\operatorname{\mathds{E}}\big(Y_{N,n}(\mathcal{J}_N)Y_{N,n'}(\mathcal{J}_N)\big)=0\quad(n\ne n').
			\label{eq:Wcov}
		\end{align}
		Their variances satisfy
		\begin{align}
			\operatorname{\mathds{E}}\big(Y_{N,n}(\mathcal{J}_N)^2\big)\longrightarrow\frac1{2n}.
			\label{eq:loop-variances}
		\end{align}
		\item For a constant $C$ independent of $N$,
		\begin{align}
			\left|\operatorname{\mathds{E}}\big(Y_{N,n}(\mathcal{J}_N)^4\big)-3\,\operatorname{\mathds{E}}\big(Y_{N,n}(\mathcal{J}_N)^2\big)^2\right|\leqslant\frac C N.
			\label{eq:fourth}
		\end{align}
		\item The statistic $Y_{N,n}(\mathcal{J}_N)$ is a degenerate $U$-statistic of order $n$ with maximal edge influence $\mathcal{O}(N^{-2})$. The same holds after variance normalization, for large $N$.
	\end{enumeratei}

\label{lem:quadratic-moments}
	Assume the hypotheses of Proposition~\ref{prop:array-joint-clt}. Then $\operatorname{Var}\big(X_N(\mathcal{J}_N)\big)$ converges to $v$, and for every $M\geqslant1$,
	\begin{align}
		\operatorname{\mathds{E}}\Big(\left\vertX_N(\mathcal{J}_N)-X_N^{(M)}(\mathcal{J}_N)\right\vert^2\Big)
		&\leqslant\frac1{N^2}\sum_{e\in E_N}\operatorname{\mathds{E}}\big(\mathcal{J}_{N,e}^4\mathds{1}\{\left\vert\mathcal{J}_{N,e}\right\vert\geqslant M\}\big),
		\label{eq:quadratic-truncation-error}\\
		\left|\operatorname{\mathds{E}}\big(X_N^{(M)}(\mathcal{J}_N)^4\big)-3\operatorname{Var}\big(X_N^{(M)}(\mathcal{J}_N)\big)^2\right|
		&\leqslant\frac{CM^4}{N^2},
		\label{eq:quadratic-cutoff-fourth}
	\end{align}
	where $C$ does not depend on $N$ or $M$. The cutoff statistic is a degenerate $U$-statistic of order $1$, with maximal edge influence $\mathcal{O}(N^{-2})$ uniformly in $M$.

We may take $\ell\geqslant4$, since smaller vectors follow by projection. This guarantees at least two loop coordinates, so that Lemma~\ref{lem:DP} (which needs $r\geqslant2$) applies also when $v=0$. Choose $M_N\to\infty$ with $M_N=o(\sqrt N)$. By Lemma~\ref{lem:quadratic-moments} and~\eqref{eq:array-fourth-integrability},
	\begin{align*}
		X_N(\mathcal{J}_N)-X_N^{(M_N)}(\mathcal{J}_N)\to0\quad\text{in }L^2
		\quad\text{and}\quad \operatorname{Var}\big(X_N^{(M_N)}(\mathcal{J}_N)\big)\to v.
	\end{align*}
	If $v>0$, apply Lemma~\ref{lem:DP} to the variance-normalized coordinates of
	\begin{align*}
		\big(X_N^{(M_N)}(\mathcal{J}_N),Y_{N,3}(\mathcal{J}_N),\ldots,Y_{N,\ell}(\mathcal{J}_N)\big).
	\end{align*}
	Their orders $1,3,\ldots,\ell$ are distinct. So the covariance matrix of the normalized vector is the identity, and condition~(iv) is vacuous. Lemmas~\ref{lem:loop-chaos} and~\ref{lem:quadratic-moments} give vanishing influences and fourth moments tending to $3$. For the quadratic coordinate the error is $\mathcal{O}(M_N^4/N^2)=o(1)$. The resulting independent Gaussian limits and the $L^2$ approximation prove the claim. If $v=0$, then $X_N(\mathcal{J}_N)\to0$ in $L^2$, and Lemma~\ref{lem:DP} applies to the loop coordinates alone.

\label{lem:tilted-edge-moments}
	Fix $\beta>0$ and $\boldsymbol{\sigma}\in\Sigma_N$. Under $\operatorname{\mathds{P}}_N^{\mathrm{tilt},\boldsymbol{\sigma}}$ the edges are independent. Moreover, uniformly over edges and configurations,
	\begin{align}
		\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big(\widetilde J_e\big)&=\frac{\beta}{\sqrt N}A_e(\boldsymbol{\sigma})+\mathcal{O}(N^{-3/2}),
		\label{eq:tilted-edge-mean}\\
		\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big(\widetilde J_e^2\big)
		&=1+\frac{(\operatorname{\mathds{E}}(J^4)-1)\beta^2}{2N}A_e(\boldsymbol{\sigma})^2+o(N^{-1}),
		\label{eq:general-planted-edge-moments}
	\end{align}
	and
	\begin{align*}
		\sup_{\boldsymbol{\sigma},e}\left|\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big(\widetilde J_e^4\big)-\operatorname{\mathds{E}}(J^4)\right|\to0.
	\end{align*}
	For the centered edges $\widetilde J_e^\circ$,
	\begin{align*}
		\sup_{\boldsymbol{\sigma},e}\left|\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big((\widetilde J_e^\circ)^2\big)-1\right|\to0
		\quad\text{and}\quad
		\sup_{\boldsymbol{\sigma},e}\left|\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big((\widetilde J_e^\circ)^4\big)-\operatorname{\mathds{E}}(J^4)\right|\to0,
	\end{align*}
	and their fourth powers are uniformly integrable:
	\begin{align*}
		\lim_{M\to\infty}
		\sup_{N,\boldsymbol{\sigma},e}\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\Big((\widetilde J_e^\circ)^4\mathds{1}\{\left\vert\widetilde J_e^\circ\right\vert\geqslant M\}\Big)=0.
	\end{align*}

The density factorizes as
	\begin{align}
		e_N(\boldsymbol{\sigma})=\prod_{e\in E_N}
		\frac{\exp\{\beta A_e(\boldsymbol{\sigma})\widetilde J_e/\sqrt N\}}
		{\operatorname{\mathds{E}}\big(\exp\{\beta A_e(\boldsymbol{\sigma})\widetilde J/\sqrt N\}\big)},
		\label{eq:general-planted-edges}
	\end{align}
	so the tilted edges are independent. It suffices to estimate the one-edge moment ratios uniformly for $\left\vertz\right\vert\leqslant C/\sqrt N$, and then to substitute $z=\beta A_e(\boldsymbol{\sigma})/\sqrt N$. On the truncated support, $\left\vertz\widetilde J\right\vert\leqslant C\varepsilon_N\to0$. Symmetry and Taylor expansion give
	\begin{align*}
		\operatorname{\mathds{E}}\big(e^{z\widetilde J}\big)&=1+\frac{z^2}{2}\operatorname{\mathds{E}}\big(\widetilde J^2\big)+\mathcal{O}(N^{-2}),
		&\operatorname{\mathds{E}}\big(\widetilde J e^{z\widetilde J}\big)&=z\operatorname{\mathds{E}}\big(\widetilde J^2\big)+\mathcal{O}(N^{-3/2}),\\
		\operatorname{\mathds{E}}\big(\widetilde J^2e^{z\widetilde J}\big)&=\operatorname{\mathds{E}}\big(\widetilde J^2\big)+\frac{z^2}{2}\operatorname{\mathds{E}}\big(\widetilde J^4\big)+o(N^{-1}),
		&\operatorname{\mathds{E}}\big(\widetilde J^4e^{z\widetilde J}\big)&=\operatorname{\mathds{E}}\big(\widetilde J^4\big)+o(1).
	\end{align*}
	The remainders follow from $\operatorname{\mathds{E}}(\widetilde J^6)=o(N)$ and $\left\vertz\widetilde J\right\vert\leqslant C\varepsilon_N\to0$. Dividing by $\operatorname{\mathds{E}}\big(e^{z\widetilde J}\big)$ and using~\eqref{eq:truncated-second-moment} and~\eqref{eq:truncated-fourth-moment}, we obtain
	\begin{align*}
		\frac{\operatorname{\mathds{E}}\big(\widetilde J e^{z\widetilde J}\big)}{\operatorname{\mathds{E}}\big(e^{z\widetilde J}\big)}&=z\operatorname{\mathds{E}}\big(\widetilde J^2\big)+\mathcal{O}(N^{-3/2})=z+\mathcal{O}(N^{-3/2}),\\
		\frac{\operatorname{\mathds{E}}\big(\widetilde J^2e^{z\widetilde J}\big)}{\operatorname{\mathds{E}}\big(e^{z\widetilde J}\big)}
		&=\operatorname{\mathds{E}}\big(\widetilde J^2\big)+\frac{z^2}{2}\Big(\operatorname{\mathds{E}}\big(\widetilde J^4\big)-\operatorname{\mathds{E}}\big(\widetilde J^2\big)^2\Big)+o(N^{-1})
		=1+\frac{\operatorname{\mathds{E}}(J^4)-1}{2}z^2+o(N^{-1}).
	\end{align*}
	This proves~\eqref{eq:tilted-edge-mean}--\eqref{eq:general-planted-edge-moments}. The tilted fourth moment also converges uniformly to $\operatorname{\mathds{E}}(J^4)$ by~\eqref{eq:truncated-fourth-moment}. Write $\mu_e:=\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}(\widetilde J_e)=\mathcal{O}(N^{-1/2})$. Expanding the powers and using H\"older's inequality with the uniform fourth-moment bound, we get
	\begin{align*}
		\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big((\widetilde J_e^\circ)^2\big)-\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big(\widetilde J_e^2\big)
		&=-\mu_e^2=\mathcal{O}(N^{-1}),\\
		\left|\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big((\widetilde J_e^\circ)^4\big)-\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big(\widetilde J_e^4\big)\right|
		&\leqslant C\big(\left\vert\mu_e\right\vert+\mu_e^2+\mu_e^4\big)=\mathcal{O}(N^{-1/2}).
	\end{align*}
	Thus centering preserves both moment limits, uniformly over edges and configurations.

	For large $M$, the event $\left\vert\widetilde J_e^\circ\right\vert\geqslant M$ implies $\left\vert\widetilde J_e\right\vert\geqslant M/2$ and $\left\vert\widetilde J_e^\circ\right\vert\leqslant2\left\vert\widetilde J_e\right\vert$, since the centering constants are uniformly bounded. The one-edge density ratios in~\eqref{eq:general-planted-edges} are uniformly bounded, so~\eqref{eq:truncated-fourth-tail} gives
	\begin{align*}
		\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\Big((\widetilde J_e^\circ)^4\mathds{1}\{\left\vert\widetilde J_e^\circ\right\vert\geqslant M\}\Big)
		\leqslant C\,\operatorname{\mathds{E}}\big(J^4\mathds{1}\{\left\vertJ\right\vert\geqslant M/2\}\big)\to0.
	\end{align*}
	This proves uniform integrability, uniformly in $N$, the edge, and the configuration.

\label{lem:tilted-approx}
	Fix $\beta>0$ and $\ell\geqslant3$.
	\begin{enumeratei}
		\item Uniformly in $\boldsymbol{\sigma}\in\Sigma_N$,
		\begin{align}
			\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\Big(\big(\widetilde X_N-\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}(\widetilde X_N)-\widetilde X_N^\circ\big)^2\Big)&\leqslant C N^{-1},
			\label{eq:quadratic-tilted-shift}\\
			\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\Big(\big(\widetilde Y_{N,n}-\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}(\widetilde Y_{N,n})-\widetilde Y_{N,n}^\circ\big)^2\Big)
			&\leqslant C(\ell)N^{-1}\quad(3\leqslant n\leqslant\ell).
			\label{eq:tilted-loop-remainder}
		\end{align}
		\item For $\boldsymbol{\sigma}=\boldsymbol{\sigma}_N\in\Sigma_N^{(\boldsymbol{n}_N)}$ with $\sup_N\left\Vertm_{\boldsymbol{n}_N}\right\Vert_2<\infty$,
		\begin{align*}
			\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big(\widetilde X_N\big)\to\frac{(\kappa-1)\beta^2}{4}\big(\operatorname{\mathds{E}}(J^4)-1\big)
			\quad\text{and}\quad
			\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big(\widetilde Y_{N,n}\big)\to\frac{(\kappa-1)\beta^n}{2n}.
		\end{align*}
	\end{enumeratei}

(i) For the quadratic statistic, $\widetilde J_e^2=(\widetilde J_e^\circ)^2+2\mu_e\widetilde J_e^\circ+\mu_e^2$ with $\mu_e=\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}(\widetilde J_e)$. Hence
	\begin{align*}
		\widetilde X_N-\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}(\widetilde X_N)-\widetilde X_N^\circ=\frac2N\sum_e\mu_e\,\widetilde J_e^\circ.
	\end{align*}
	Independence and Lemma~\ref{lem:tilted-edge-moments} bound its variance by $CN^{-1}$, which proves~\eqref{eq:quadratic-tilted-shift}.

	For the loop statistic, write $\tau_e:=\widetilde J_e^\circ/\sqrt N$ and $a_e:=\mu_e/\sqrt N$. Then $\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}(\tau_e)=0$, $\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}(\tau_e^2)\leqslant C/N$, and $\left\verta_e\right\vert\leqslant C/N$, uniformly in $e$ and $\boldsymbol{\sigma}$. Expanding the loop product and subtracting its expectation gives
	\begin{align*}
		\prod_{e\in\gamma}(\tau_e+a_e)-\prod_{e\in\gamma}a_e
		=\sum_{\emptyset\ne A\subseteq\gamma}\left(\prod_{e\in\gamma\setminus A}a_e\right)\prod_{e\in A}\tau_e.
	\end{align*}
	Hence
	\begin{align*}
		\widetilde Y_{N,n}-\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}(\widetilde Y_{N,n})-\widetilde Y_{N,n}^\circ
		=\sum_{k=1}^{n-1}\sum_{\left\vertA\right\vert=k}
		\left(\sum_{\substack{\gamma\in\mathcal{L}_n\\A\subseteq\gamma}}\prod_{e\in\gamma\setminus A}a_e\right)\prod_{e\in A}\tau_e,
	\end{align*}
	where the sum over $A$ runs over the $k$-edge subgraphs contained in some loop of length $n$. Define $N_n(A):=\#\{\gamma\in\mathcal{L}_n:A\subseteq\gamma\}$. Products over distinct edge sets are orthogonal, since an edge lying in exactly one of $A,A'$ contributes a factor $\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}(\tau_e)=0$. Also $\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big((\prod_{e\in A}\tau_e)^2\big)=\prod_{e\in A}\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}(\tau_e^2)$. Thus
	\begin{align*}
		\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\Big(\big(\widetilde Y_{N,n}-\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}(\widetilde Y_{N,n})-\widetilde Y_{N,n}^\circ\big)^2\Big)
		\leqslant C(n)\sum_{k=1}^{n-1}N^{-2(n-k)}N^{-k}\sum_{\left\vertA\right\vert=k}N_n(A)^2.
	\end{align*}
	Let $A$ be a $k$-edge proper subgraph of a loop of length $n$, consisting of $p\geqslant1$ vertex-disjoint paths. Then $\left\vertV(A)\right\vert=k+p$. For fixed $k$ and $p$ there are at most $C(n)N^{k+p}$ such $A$, and $N_n(A)\leqslant C(n)N^{n-k-p}$ (choose the remaining $n-k-p$ vertices of the loop and a cyclic arrangement). Hence
	\begin{align*}
		\sum_{\left\vertA\right\vert=k}N_n(A)^2\leqslant C(n)\sum_{p=1}^{n-k}N^{k+p}N^{2(n-k-p)}
		\leqslant C(n)N^{2n-k-1}.
	\end{align*}
	Each term in the preceding second-moment bound is therefore $\mathcal{O}(N^{-1})$, which proves~\eqref{eq:tilted-loop-remainder}.

	(ii) Summing~\eqref{eq:general-planted-edge-moments} and using~\eqref{eq:truncated-second-moment} gives
	\begin{align*}
		\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big(\widetilde X_N\big)=\frac{(\operatorname{\mathds{E}}(J^4)-1)\beta^2}{2N^2}\sum_e A_e(\boldsymbol{\sigma})^2+o(1)
		\to\frac{(\kappa-1)\beta^2}{4}\big(\operatorname{\mathds{E}}(J^4)-1\big),
	\end{align*}
	since~\eqref{eq:selfoverlap} gives $\sum_e A_e(\boldsymbol{\sigma})^2=(\kappa-1)N^2/2+\mathcal{O}(N)$ on a bounded magnetization window.

	For the loop means, independence and~\eqref{eq:tilted-edge-mean} yield
	\begin{align*}
		\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big(\widetilde Y_{N,n}\big)
		=\frac{\beta^n}{N^n}\sum_{\gamma\in\mathcal{L}_n}\prod_{e\in\gamma}A_e(\boldsymbol{\sigma})+o(1).
	\end{align*}
	Since $A_{ij}(\boldsymbol{\sigma})=\phi(\sigma_i)^{\intercal}\phi(\sigma_j)$ and each loop is counted $2n$ times by its ordered vertex sequences, we obtain, with $i_{n+1}:=i_1$,
	\begin{align*}
		\sum_{\gamma\in\mathcal{L}_n}\prod_{e\in\gamma}A_e(\boldsymbol{\sigma})
		=\frac1{2n}\sum_{\substack{i_1,\ldots,i_n\\\text{all distinct}}}
		\prod_{r=1}^n\phi(\sigma_{i_r})^{\intercal}\phi(\sigma_{i_{r+1}})
		=\frac1{2n}\operatorname{Tr}\left[\left(\sum_{i=1}^N\phi(\sigma_i)\phi(\sigma_i)^{\intercal}\right)^n\right]+\mathcal{O}(N^{n-1}).
	\end{align*}
	For the second equality, expand the matrix power and use
	\begin{align*}
		\operatorname{Tr}\big[(v_1v_1^{\intercal})\cdots(v_nv_n^{\intercal})\big]
		=(v_1^{\intercal}v_2)\cdots(v_n^{\intercal}v_1).
	\end{align*}
	The terms with repeated indices number $\mathcal{O}(N^{n-1})$ and are uniformly bounded, so after division by $N^n$ they contribute $\mathcal{O}(N^{-1})$. Moreover, $n_x(\boldsymbol{\sigma})/N\to1/\kappa$, so
	\begin{align*}
		\frac1N\sum_{i=1}^N\phi(\sigma_i)\phi(\sigma_i)^{\intercal}
		=\sum_{x=1}^{\kappa}\frac{n_x(\boldsymbol{\sigma})}N\phi(x)\phi(x)^{\intercal}
		\to\frac1\kappa\sum_{x=1}^{\kappa}\phi(x)\phi(x)^{\intercal}=\Pi.
	\end{align*}
	Since $\Pi^n=\Pi$ and $\operatorname{Tr}(\Pi)=\kappa-1$, it follows that
	$\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}(\widetilde Y_{N,n})\to(\kappa-1)\beta^n/(2n)$.

\label{prop:general-planted-cycles}
	Fix $\beta>0$ and $\ell\geqslant3$. Under the product law of the truncated disorder,
	\begin{align*}
		\big( \widetilde X_N, \widetilde Y_{N,3},\ldots, \widetilde Y_{N,\ell}\big)
		\Longrightarrow
		\operatorname{N}\left(0,\frac{\operatorname{\mathds{E}}(J^4)-1}{2}\right)
			\otimes\bigotimes_{n=3}^{\ell}\operatorname{N}\left(0,\frac1{2n}\right).
	\end{align*}
	Let $(\boldsymbol{n}_N)$ be profiles with $\sup_N\left\Vertm_{\boldsymbol{n}_N}\right\Vert_2<\infty$ and let $\boldsymbol{\sigma}_N\in\Sigma_N^{(\boldsymbol{n}_N)}$. Under $\operatorname{\mathds{P}}_N^{\mathrm{tilt},\boldsymbol{\sigma}_N}$, the same vector converges to a Gaussian vector with independent coordinates, the same variances, and respective means
	\begin{align*}
		\frac{(\kappa-1)\beta^2}{4}\big(\operatorname{\mathds{E}}(J^4)-1\big)
		\quad\text{and}\quad \frac{(\kappa-1)\beta^n}{2n},\quad 3\leqslant n\leqslant\ell.
	\end{align*}
	Consequently, under the product law and under the tilted law, respectively,
	\begin{align*}
		\widetilde G_{N,\ell}\Longrightarrow\operatorname{N}\big(0,\varphi_{\kappa,J,\ell}(\beta^2)\big)
		\quad\text{and}\quad
		\widetilde G_{N,\ell}\Longrightarrow
			\operatorname{N}\big(\varphi_{\kappa,J,\ell}(\beta^2),\varphi_{\kappa,J,\ell}(\beta^2)\big).
	\end{align*}

Under the product law, the edges $\widetilde J_e$ are independent and centered by symmetry. By~\eqref{eq:truncated-second-moment} and~\eqref{eq:truncated-fourth-moment},
	\begin{align*}
		\max_{e\in E_N}\left\vert\operatorname{\mathds{E}}\big(\widetilde J_e^2\big)-1\right\vert\to0
		\quad\text{and}\quad \frac1{N^2}\sum_{e\in E_N}\operatorname{Var}\big(\widetilde J_e^2\big)
		=\frac{\binom N2}{N^2}\Big(\operatorname{\mathds{E}}\big(\widetilde J^4\big)-\operatorname{\mathds{E}}\big(\widetilde J^2\big)^2\Big)
		\to\frac{\operatorname{\mathds{E}}(J^4)-1}{2}.
	\end{align*}
	Moreover,~\eqref{eq:truncated-fourth-tail} gives the uniform integrability of their fourth powers. Thus all assumptions of Proposition~\ref{prop:array-joint-clt} hold with $\mathcal{J}_{N,e}=\widetilde J_e$ and $v=(\operatorname{\mathds{E}}(J^4)-1)/2$, which proves the first assertion.

	For the tilted law, Lemma~\ref{lem:tilted-edge-moments} verifies the assumptions of Proposition~\ref{prop:array-joint-clt} for $\mathcal{J}_{N,e}=\widetilde J_e^\circ$, with $v=(\operatorname{\mathds{E}}(J^4)-1)/2$. Thus $(\widetilde X_N^\circ,\widetilde Y_{N,3}^\circ,\ldots,\widetilde Y_{N,\ell}^\circ)$ has the centered Gaussian limit of the first assertion. By Lemma~\ref{lem:tilted-approx}, the expectation of any bounded Lipschitz function of the original vector differs by $o(1)$ from that of the centered vector translated by the limiting means. This proves the tilted assertion. The claims for $\widetilde G_{N,\ell}$ follow from its definition, since
	\begin{align*}
		\frac{(\kappa-1)\beta^2}{2}\cdot\frac{(\kappa-1)\beta^2}{4}\big(\operatorname{\mathds{E}}(J^4)-1\big)
		+(\kappa-1)\sum_{n=3}^{\ell}\beta^n\frac{(\kappa-1)\beta^n}{2n}
		=\varphi_{\kappa,J,\ell}(\beta^2)
	\end{align*}
	for the mean, and the variance is computed in the same way.

We show that $\mathcal{Z}_N^{(\boldsymbol{n}_N)}$ is close in $L^2$ to an explicit function of the loop statistics, then take logarithms. Fix a sequence $(\boldsymbol{n}_N)$ in a bounded magnetization window. Lemma~\ref{lem:general-profile-moments} gives $\operatorname{\mathds{E}}\big( (\mathcal{Z}_N^{(\boldsymbol{n}_N)})^2\big)\to e^{\varphi_{\kappa,J}(\beta^2)}$.
	We show that the loop statistics account for this entire second moment. Fix $\ell\geqslant3$ and $B>0$, and define the bounded continuous function
	\begin{align*}
		f_{\ell,B}(x):=\min\big\{e^{x-\varphi_{\kappa,J,\ell}(\beta^2)/2},B\big\}.
	\end{align*}
	Our goal is the $L^2$ approximation
	\begin{align}
		\lim_{\ell\to\infty}\lim_{B\to\infty}\limsup_{N\to\infty}
		\operatorname{\mathds{E}}\Big(\big(\mathcal{Z}_N^{(\boldsymbol{n}_N)}-f_{\ell,B}(\widetilde G_{N,\ell})\big)^2\Big)=0.
		\label{eq:general-lognormal-approximation}
	\end{align}
	By~\eqref{eq:general-planted-law},
	\begin{align*}
		\operatorname{\mathds{E}}\Big(\mathcal{Z}_N^{(\boldsymbol{n}_N)}f_{\ell,B}(\widetilde G_{N,\ell})\Big)
		=\operatorname{\mathds{E}}_{\boldsymbol{\sigma}}^{(\boldsymbol{n}_N)}\Big(\operatorname{\mathds{E}}^{\mathrm{tilt},\boldsymbol{\sigma}}\big(f_{\ell,B}(\widetilde G_{N,\ell})\big)\Big).
	\end{align*}
	The inner expectation is the same for all configurations of this profile, because the product law and $\widetilde G_{N,\ell}$ are invariant under permutations of the vertices. Thus Proposition~\ref{prop:general-planted-cycles} gives
	\begin{align*}
		\lim_{N\to\infty}\operatorname{\mathds{E}}\Big(\big( \mathcal{Z}_N^{(\boldsymbol{n}_N)}-f_{\ell,B}( \widetilde G_{N,\ell})\big)^2\Big)
		=e^{\varphi_{\kappa,J}(\beta^2)}-2\operatorname{\mathds{E}}\big(f_{\ell,B}(\zeta'_{\ell})\big)+\operatorname{\mathds{E}}\big(f_{\ell,B}(\zeta_{\ell})^2\big),
	\end{align*}
	where $\zeta_{\ell}\sim\operatorname{N}(0,\varphi_{\kappa,J,\ell}(\beta^2))$ and $\zeta'_{\ell}\sim\operatorname{N}(\varphi_{\kappa,J,\ell}(\beta^2),\varphi_{\kappa,J,\ell}(\beta^2))$. The density of the law of $\zeta'_\ell$ with respect to that of $\zeta_\ell$ is $e^{x-\varphi_{\kappa,J,\ell}(\beta^2)/2}$. Letting $B\to\infty$, monotone convergence turns the right-hand side into
	\begin{align*}
		e^{\varphi_{\kappa,J}(\beta^2)}-2e^{\varphi_{\kappa,J,\ell}(\beta^2)}
			+e^{\varphi_{\kappa,J,\ell}(\beta^2)}
		=e^{\varphi_{\kappa,J}(\beta^2)}-e^{\varphi_{\kappa,J,\ell}(\beta^2)},
	\end{align*}
	which tends to zero as $\ell\to\infty$. This proves~\eqref{eq:general-lognormal-approximation}. For a bounded Lipschitz function $h$, the Cauchy--Schwarz inequality gives
	\begin{align*}
		\left|\operatorname{\mathds{E}}\big(h( \mathcal{Z}_N^{(\boldsymbol{n}_N)})\big)-\operatorname{\mathds{E}}\big(h(f_{\ell,B}( \widetilde G_{N,\ell}))\big)\right|
		\leqslant\operatorname{Lip}(h)
			\left(\operatorname{\mathds{E}}\Big(\big( \mathcal{Z}_N^{(\boldsymbol{n}_N)}
				-f_{\ell,B}( \widetilde G_{N,\ell})\big)^2\Big)\right)^{1/2}.
	\end{align*}
	Let first $N\to\infty$, then $B\to\infty$, and finally $\ell\to\infty$. The Gaussian approximants converge in law to $e^{\zeta-\varphi_{\kappa,J}(\beta^2)/2}$ with $\zeta\sim\operatorname{N}(0,\varphi_{\kappa,J}(\beta^2))$. This proves the lognormal limit of $\mathcal{Z}_N^{(\boldsymbol{n}_N)}$. Since the limit is strictly positive, the continuous mapping theorem gives
	\begin{align}
		\ln \mathcal{Z}_N^{(\boldsymbol{n}_N)}
			\Longrightarrow\operatorname{N}\left(-\frac12\varphi_{\kappa,J}(\beta^2),
										\varphi_{\kappa,J}(\beta^2)\right).
		\label{eq:general-profile-lognormal}
	\end{align}
	No estimate on negative moments of $\mathcal{Z}_N^{(\boldsymbol{n}_N)}$ is needed.

	Finally, take logarithms in~\eqref{eq:profile-factorization} and substitute~\eqref{eq:general-self-kernel} and~\eqref{eq:general-variance}. Since $\mathfrak{R}_N^{(1)}\to0$ on the window, the limiting mean correction is
	\begin{align*}
		\frac{\mu_4\beta^4(\kappa-1)(\kappa^2-3\kappa+3)}{48}-\frac12\varphi_{\kappa,J}(\beta^2)
		=-\frac12\varphi_{\kappa}(\beta^2)
			+\frac{\mu_4\beta^4(\kappa-1)(\kappa^2-6\kappa+6)}{48}.
	\end{align*}
	The coupling~\eqref{eq:truncation-coupling} transfers the distributional statement to the original disorder.

\label{prop:profile-equiv}
	Assume that $0<\beta^2<\alpha_c(\kappa)$ and $\alpha<\alpha_c(\kappa)$. For the original disorder $J$,
	\begin{align}
		\sum_{\boldsymbol{n}}\left|\big\langle\mathds{1}\{n(\boldsymbol{\sigma})=\boldsymbol{n}\}\big\rangle_{\varrho_{N,\beta}}
						-\widehat P_{\boldsymbol{n}}\right|&\longrightarrow0
						\quad\text{in probability, and}
		\label{eq:profile-total-variation}\\
		\ln Z_N(\beta;J)-\ln Z_N^{(\boldsymbol{n}^*)}(\beta;J)
			-\ln\frac{\kappa^N}{\left\vert\Sigma_N^{(\boldsymbol{n}^*)}\right\vert}
		&\longrightarrow-\frac{\kappa-1}{2}\ln(1-\alpha)
						\quad\text{in probability}.
		\label{eq:transfer-full}
	\end{align}

Throughout, $\sum_{\leqslant L}$ and $\sum_{>L}$ denote the profile sums restricted to $\left\Vertm_{\boldsymbol{n}}\right\Vert_2\leqslant L$ and to $\left\Vertm_{\boldsymbol{n}}\right\Vert_2>L$, for an arbitrary $L>0$.
	By~\eqref{eq:general-self-kernel} and $\left\Vertm_{\boldsymbol{n}^*}\right\Vert_2^2=\mathcal{O}(N^{-1})$,
	\begin{align*}
		\ln w_{\boldsymbol{n}}=\frac\alpha2\left\Vertm_{\boldsymbol{n}}\right\Vert_2^2
		+o(1)+\mathcal{O}\left(\frac{\left\Vertm_{\boldsymbol{n}}\right\Vert_2^2}{N}\right),
	\end{align*}
	uniformly in the profile.
	Fix $\alpha<\gamma<\gamma'<\alpha_c(\kappa)$. The expansion gives $w_{\boldsymbol{n}}\leqslant C e^{\gamma\left\Vertm_{\boldsymbol{n}}\right\Vert_2^2/2}$ for all sufficiently large $N$, and $w_{\boldsymbol{n}}-e^{\alpha\left\Vertm_{\boldsymbol{n}}\right\Vert_2^2/2}\to0$ uniformly on every fixed window.

	\emph{Profile equivalence.} Set
	\begin{align*}
		\mathrm{Den}_N:=\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}\mathcal{Z}_N^{(\boldsymbol{n})}.
	\end{align*}
	The Gibbs profile probabilities are $P_{\boldsymbol{n}}w_{\boldsymbol{n}}\mathcal{Z}_N^{(\boldsymbol{n})}/\mathrm{Den}_N$, whereas $\widehat P_{\boldsymbol{n}}=P_{\boldsymbol{n}}w_{\boldsymbol{n}}/\sum_{\boldsymbol{n}'}P_{\boldsymbol{n}'}w_{\boldsymbol{n}'}$. We use the identity
	\begin{align*}
		\widehat P_{\boldsymbol{n}}
		-\frac{P_{\boldsymbol{n}}w_{\boldsymbol{n}}\mathcal{Z}_N^{(\boldsymbol{n}^*)}}{\mathrm{Den}_N}
		=\frac{\widehat P_{\boldsymbol{n}}}{\mathrm{Den}_N}
		\sum_{\boldsymbol{n}'}P_{\boldsymbol{n}'}w_{\boldsymbol{n}'}
		\big(\mathcal{Z}_N^{(\boldsymbol{n}')}-\mathcal{Z}_N^{(\boldsymbol{n}^*)}\big).
	\end{align*}
	Adding and subtracting $P_{\boldsymbol{n}}w_{\boldsymbol{n}}\mathcal{Z}_N^{(\boldsymbol{n}^*)}/\mathrm{Den}_N$ therefore gives
	\begin{align}
		\sum_{\boldsymbol{n}}\left|\frac{P_{\boldsymbol{n}}w_{\boldsymbol{n}}\mathcal{Z}_N^{(\boldsymbol{n})}}{\mathrm{Den}_N}
		-\widehat P_{\boldsymbol{n}}\right|
		\leqslant 2\,\frac{\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}
		\left\vert\mathcal{Z}_N^{(\boldsymbol{n})}-\mathcal{Z}_N^{(\boldsymbol{n}^*)}\right\vert}{\mathrm{Den}_N}.
		\label{eq:profile-tv-bound}
	\end{align}

	We first estimate the numerator of~\eqref{eq:profile-tv-bound}. Since $\operatorname{\mathds{E}}\big(\mathcal{Z}_N^{(\boldsymbol{n})}\big)=1$,
	\begin{align}
		\operatorname{\mathds{E}}\Big(\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}
		\left\vert\mathcal{Z}_N^{(\boldsymbol{n})}-\mathcal{Z}_N^{(\boldsymbol{n}^*)}\right\vert\Big)
		&\leqslant\sum_{\leqslant L}P_{\boldsymbol{n}}w_{\boldsymbol{n}}\,
		\operatorname{\mathds{E}}\big(\left\vert\mathcal{Z}_N^{(\boldsymbol{n})}-\mathcal{Z}_N^{(\boldsymbol{n}^*)}\right\vert\big)
		+2\sum_{>L}P_{\boldsymbol{n}}w_{\boldsymbol{n}}\nonumber\\
		&\leqslant C e^{\gamma L^2/2}\sum_{\leqslant L}P_{\boldsymbol{n}}\,
		\operatorname{\mathds{E}}\big(\left\vert\mathcal{Z}_N^{(\boldsymbol{n})}-\mathcal{Z}_N^{(\boldsymbol{n}^*)}\right\vert\big)
		+2\sum_{>L}P_{\boldsymbol{n}}w_{\boldsymbol{n}}.
		\label{eq:general-profile-split}
	\end{align}
	Since $\sum_{\leqslant L}P_{\boldsymbol{n}}\leqslant1$, the first term is at most
	\begin{align*}
		C e^{\gamma L^2/2}\sup_{\left\Vertm_{\boldsymbol{n}}\right\Vert_2\leqslant L}
		\left(\operatorname{\mathds{E}}\Big(\big(\mathcal{Z}_N^{(\boldsymbol{n})}-\mathcal{Z}_N^{(\boldsymbol{n}^*)}\big)^2\Big)\right)^{1/2},
	\end{align*}
	which tends to $0$ by~\eqref{eq:general-profile-collapse}. For the second term,
	\begin{align}
		\sum_{>L}P_{\boldsymbol{n}}w_{\boldsymbol{n}}
		&\leqslant C \sum_{>L}P_{\boldsymbol{n}} e^{\gamma\left\Vertm_{\boldsymbol{n}}\right\Vert_2^2/2}\nonumber\\
		&\leqslant C e^{-(\gamma'-\gamma)L^2/2}\, \operatorname{\mathds{E}}_{\boldsymbol{\sigma}}\big(e^{\gamma'\left\Vertm(\boldsymbol{\sigma})\right\Vert_2^2/2}\big)
		\leqslant C\big(1-\gamma'\eta_\phi(\kappa)\big)^{-\kappa/2}
		e^{-(\gamma'-\gamma)L^2/2}.
		\label{eq:general-profile-tail}
	\end{align}
	In the last inequality we applied Lemma~\ref{lem:expmoment} to $W:=\sqrt{\gamma'}\phi(\sigma_1)$, whose optimal sub-Gaussian constant is $\gamma'\eta_\phi(\kappa)<1$ by Lemma~\ref{lem:eta-phi}. Letting $N\to\infty$ in~\eqref{eq:general-profile-split}, we get
	\begin{align*}
		\limsup_{N\to\infty}\operatorname{\mathds{E}}\Big(\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}
		\left\vert\mathcal{Z}_N^{(\boldsymbol{n})}-\mathcal{Z}_N^{(\boldsymbol{n}^*)}\right\vert\Big)
		\leqslant C e^{-(\gamma'-\gamma)L^2/2}.
	\end{align*}
	Since $L$ is arbitrary,
	\begin{align}
		\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}
		\left\vert\mathcal{Z}_N^{(\boldsymbol{n})}-\mathcal{Z}_N^{(\boldsymbol{n}^*)}\right\vert
		\to0\quad\text{in }L^1.
		\label{eq:general-profile-weighted}
	\end{align}

	Next we compute the total annealed weight. The weights $w_{\boldsymbol{n}}$ converge to $e^{\alpha\left\Vertm_{\boldsymbol{n}}\right\Vert_2^2/2}$ uniformly on bounded windows, and~\eqref{eq:general-profile-tail} controls both $w_{\boldsymbol{n}}$ and $e^{\alpha\left\Vertm_{\boldsymbol{n}}\right\Vert_2^2/2}$ outside them. Hence
	\begin{align*}
		\sum_{\boldsymbol{n}}P_{\boldsymbol{n}} \left(w_{\boldsymbol{n}} - e^{\alpha\left\Vertm_{\boldsymbol{n}}\right\Vert_2^2/2}\right) \to 0.
	\end{align*}
	Under the uniform measure, $m(\boldsymbol{\sigma})\Longrightarrow g_0\sim\operatorname{N}(0,\Pi)$ by the central limit theorem. Lemma~\ref{lem:expmoment} with $W:=\sqrt\gamma\,\phi(\sigma_1)$ gives $\sup_N\operatorname{\mathds{E}}_{\boldsymbol{\sigma}}\big(e^{\gamma\left\Vertm\right\Vert_2^2/2}\big)<\infty$. Since $\gamma>\alpha$, the variables $e^{\alpha\left\Vertm\right\Vert_2^2/2}$ are uniformly integrable (trivially if $\alpha=0$). Therefore
	\begin{align}
		\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}
		\to\operatorname{\mathds{E}}\big(e^{\alpha\left\Vertg_0\right\Vert_2^2/2}\big)=(1-\alpha)^{-(\kappa-1)/2}.
		\label{eq:general-profile-tilt}
	\end{align}
	The last identity holds because $\left\Vertg_0\right\Vert_2^2$ has the chi-squared law with $\kappa-1$ degrees of freedom. By~\eqref{eq:general-profile-weighted},
	\begin{align*}
		\mathrm{Den}_N-\mathcal{Z}_N^{(\boldsymbol{n}^*)}\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}
		\to0\quad\text{in }L^1.
	\end{align*}
	By~\eqref{eq:general-profile-lognormal}, $\mathcal{Z}_N^{(\boldsymbol{n}^*)}$ converges in law to an almost surely positive limit, so $1/\mathcal{Z}_N^{(\boldsymbol{n}^*)}=\mathcal{O}_{\operatorname{\mathds{P}}}(1)$. Dividing by $\mathcal{Z}_N^{(\boldsymbol{n}^*)}$ yields
	\begin{align*}
		\frac{\mathrm{Den}_N}{\mathcal{Z}_N^{(\boldsymbol{n}^*)}}
		\to(1-\alpha)^{-(\kappa-1)/2}\quad\text{in probability}.
	\end{align*}
	In particular,
	\begin{align}
		(\mathrm{Den}_N)^{-1} =\left(\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}\mathcal{Z}_N^{(\boldsymbol{n})}\right)^{-1}
		=\mathcal{O}_{\operatorname{\mathds{P}}}(1).
		\label{eq:general-gibbs-denominator}
	\end{align}
	Now~\eqref{eq:profile-tv-bound}, \eqref{eq:general-profile-weighted} and~\eqref{eq:general-gibbs-denominator} prove~\eqref{eq:profile-total-variation} for the truncated disorder.

	\emph{Free-energy comparison.} The profile decomposition~\eqref{eq:profile-factorization} gives
	\begin{align*}
		\frac{Z_N(\beta;\widetilde J)}{Z_N^{(\boldsymbol{n}^*)}(\beta;\widetilde J)}\cdot
		\frac{\left\vert\Sigma_N^{(\boldsymbol{n}^*)}\right\vert}{\kappa^N}
		=\frac{\mathrm{Den}_N}{\mathcal{Z}_N^{(\boldsymbol{n}^*)}}
		\to(1-\alpha)^{-(\kappa-1)/2}\quad\text{in probability}.
	\end{align*}
	Taking logarithms proves~\eqref{eq:transfer-full}. Finally, the coupling~\eqref{eq:truncation-coupling} transfers both assertions from $\widetilde J$ to the original disorder.

\label{lem:general-color-clt}
	Let $0<\beta<\beta_{\max}(\kappa)$ and $g\sim\operatorname{N}(0,\Pi/(1-\alpha))$. For every bounded continuous $f:\mathds{R}^{\kappa}\to\mathds{R}$,
	\begin{align}
		\big\langle f(m)\big\rangle_{\varrho_{N,\beta}}
			\to\operatorname{\mathds{E}}\big(f(g)\big)\quad\text{in probability}.
		\label{eq:general-color-clt}
	\end{align}
	Moreover, there are $C,c>0$ such that, for every $L>0$,
	\begin{align}
		\big\langle\mathds{1}\{\left\Vertm\right\Vert_2>L\}\big\rangle_{\varrho_{N,\beta}}
			\leqslant C e^{-cL^2}+o_{\operatorname{\mathds{P}}}(1).
		\label{eq:general-color-tail}
	\end{align}

We first work with the truncated disorder. The total variation comparison~\eqref{eq:profile-total-variation} gives
	\begin{align*}
		\big\langle f(m)\big\rangle_{\varrho_{N,\beta}}
		=\sum_{\boldsymbol{n}}\widehat P_{\boldsymbol{n}}f(m_{\boldsymbol{n}})+o_{\operatorname{\mathds{P}}}(1)
		=\frac{\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}f(m_{\boldsymbol{n}})}{\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}}+o_{\operatorname{\mathds{P}}}(1).
	\end{align*}
	Since $f$ is bounded, the tail estimate~\eqref{eq:general-profile-tail} and the uniform convergence $w_{\boldsymbol{n}}-e^{\alpha\left\Vertm_{\boldsymbol{n}}\right\Vert_2^2/2}\to0$ on each fixed window imply
	\begin{align*}
		\frac{\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}f(m_{\boldsymbol{n}})}{\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}}
		=\frac{\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}e^{\alpha\left\Vertm_{\boldsymbol{n}}\right\Vert_2^2/2}f(m_{\boldsymbol{n}})}{\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}e^{\alpha\left\Vertm_{\boldsymbol{n}}\right\Vert_2^2/2}}+o(1).
	\end{align*}
	Choose $\alpha<\gamma<\alpha_c(\kappa)$. Lemma~\ref{lem:expmoment} gives $\sup_N\operatorname{\mathds{E}}_{\boldsymbol{\sigma}}\big(e^{\gamma\left\Vertm\right\Vert_2^2/2}\big)<\infty$, so $e^{\alpha\left\Vertm\right\Vert_2^2/2}$ is uniformly integrable (trivially when $\alpha=0$). The central limit theorem for $m$ under the uniform measure therefore yields, with $g_0\sim\operatorname{N}(0,\Pi)$,
	\begin{align*}
		\big\langle f(m)\big\rangle_{\varrho_{N,\beta}}
		\to\frac{\operatorname{\mathds{E}}\big(f(g_0)e^{\alpha\left\Vertg_0\right\Vert_2^2/2}\big)}{\operatorname{\mathds{E}}\big(e^{\alpha\left\Vertg_0\right\Vert_2^2/2}\big)}
		=\operatorname{\mathds{E}}\big(f(g)\big)\quad\text{in probability}.
	\end{align*}
	The last equality holds because the quadratic tilt multiplies the covariance of $g_0$ on the range of $\Pi$ by $(1-\alpha)^{-1}$. This proves~\eqref{eq:general-color-clt}.

	For~\eqref{eq:general-color-tail}, the same total variation comparison gives
	\begin{align*}
		\big\langle\mathds{1}\{\left\Vertm\right\Vert_2>L\}\big\rangle_{\varrho_{N,\beta}}
		=\frac{\sum_{\left\Vertm_{\boldsymbol{n}}\right\Vert_2>L}P_{\boldsymbol{n}}w_{\boldsymbol{n}}}{\sum_{\boldsymbol{n}}P_{\boldsymbol{n}}w_{\boldsymbol{n}}}+o_{\operatorname{\mathds{P}}}(1).
	\end{align*}
	The numerator is bounded by $Ce^{-cL^2}$ by~\eqref{eq:general-profile-tail}, and the denominator converges to a positive constant by~\eqref{eq:general-profile-tilt}. Finally, the coupling~\eqref{eq:truncation-coupling} transfers both assertions from $\widetilde J$ to $J$.

\label{lem:general-CN-key}
	Fix $L>0$ and $0<\beta^2<T<\alpha_c(\kappa)$, and let $K_0\sim\operatorname{N}(0,\Pi\otimes\Pi)$. For every $F\in\mathcal{G}_{(T)}$,
	\begin{align}
		\sup_{\left\Vertm_{\boldsymbol{n}}\right\Vert_2,\left\Vertm_{\boldsymbol{n}'}\right\Vert_2\leqslant L}
		\operatorname{\mathds{E}}\Big(\Big| U_N^{(\boldsymbol{n}),(\boldsymbol{n}')}(F)
			- \mathcal{Z}_N^{(\boldsymbol{n})} \mathcal{Z}_N^{(\boldsymbol{n}')}
				e^{-\varphi_{\kappa,J}(\beta^2)}\operatorname{\mathds{E}}\big(F(K_0)\big)\Big|\Big)\to0.
		\label{eq:general-CN-key}
	\end{align}

Fix profiles in the stated window and abbreviate $U_N:=U_N^{(\boldsymbol{n}),(\boldsymbol{n}')}$.

	\smallskip\noindent\textbf{Step 1 (centered compactly supported functions).} First let $F$ be continuous and compactly supported, with $\operatorname{\mathds{E}}\big(F(K_0)\big)=0$. Write
	\begin{align*}
		U_N(F)=\operatorname{\mathds{E}}_{\boldsymbol{\sigma}}^{(\boldsymbol{n})}\big(e_N(\boldsymbol{\sigma})X_{\boldsymbol{\sigma}}\big),\quad
		X_{\boldsymbol{\sigma}}:=\operatorname{\mathds{E}}_{\boldsymbol{\tau}}^{(\boldsymbol{n}')}\Big(e_N(\boldsymbol{\tau})e^{-\Lambda_N(\boldsymbol{\sigma},\boldsymbol{\tau})}F\big(\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})\big)\Big).
	\end{align*}
	Since $\operatorname{\mathds{E}}\big(\operatorname{\mathds{E}}_{\boldsymbol{\sigma}}^{(\boldsymbol{n})}(e_N(\boldsymbol{\sigma}))\big)=1$, the density $e_N(\boldsymbol{\sigma})$ defines a probability measure on the disorder and the uniform configuration $\boldsymbol{\sigma}$. The Cauchy--Schwarz inequality under this measure, followed by~\eqref{eq:general-triple-kernel}, gives
	\begin{align*}
		\Big(\operatorname{\mathds{E}}\big(\left\vertU_N(F)\right\vert\big)\Big)^2
		&\leqslant\operatorname{\mathds{E}}\Big(\operatorname{\mathds{E}}_{\boldsymbol{\sigma}}^{(\boldsymbol{n})}\big(e_N(\boldsymbol{\sigma})X_{\boldsymbol{\sigma}}^2\big)\Big)\\
		&=\operatorname{\mathds{E}}_{\boldsymbol{\sigma},\boldsymbol{\tau},\boldsymbol{\tau}'}^{(\boldsymbol{n}),(\boldsymbol{n}'),(\boldsymbol{n}')}
		\Big(e^{\Lambda_N(\boldsymbol{\tau},\boldsymbol{\tau}')+\mathfrak{R}_N^{(3)}(\boldsymbol{\sigma},\boldsymbol{\tau},\boldsymbol{\tau}')}
		F\big(\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})\big)F\big(\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau}')\big)\Big).
	\end{align*}
	Lemma~\ref{lem:general-kernels} shows that the remainders vanish in probability and are globally bounded. Lemma~\ref{lem:profile-clt} makes the three limiting overlaps independent, and Lemma~\ref{lem:profile-moments}(i) with exponent $T>\beta^2$ gives uniform integrability. Thus the last expression converges to
	\begin{align*}
		e^{\varphi_{\kappa,J}(\beta^2)-\varphi_{\kappa}(\beta^2)}\,
		\operatorname{\mathds{E}}\big(e^{\beta^2\xi(K_0)}\big)\,\operatorname{\mathds{E}}\big(F(K_0)\big)^2=0.
	\end{align*}

	\smallskip\noindent\textbf{Step 2 (boundedness).} The multiplier of $F(\mathscr{R})$ in~\eqref{eq:general-UN} has disorder expectation one, by the definition of $\Lambda_N$. Hence
	\begin{align*}
		\operatorname{\mathds{E}}\big(\left\vertU_N(F)\right\vert\big)
		\leqslant\operatorname{\mathds{E}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}\big(\left\vertF(\mathscr{R})\right\vert\big)
		\leqslant C(T,L)\left\VertF\right\Vert_{(T)},
	\end{align*}
	uniformly over the profile window, by Lemma~\ref{lem:profile-moments}(i) with exponent $T$.

	\smallskip\noindent\textbf{Step 3 (centered functions in $\mathcal{G}_{(T)}$).} The centered compactly supported functions are dense in $\{F\in\mathcal{G}_{(T)}:\operatorname{\mathds{E}}(F(K_0))=0\}$ for the norm $\left\Vert\cdot\right\Vert_{(T)}$. Indeed, choose a continuous compactly supported $h\geqslant0$ with $\operatorname{\mathds{E}}\big(h(K_0)\big)=1$, and continuous cutoffs $0\leqslant\chi_r\leqslant1$ equal to one on the ball of radius $r$ and to zero outside the ball of radius $2r$. For centered $F$, define $F_r:=F\chi_r-\operatorname{\mathds{E}}\big(F(K_0)\chi_r(K_0)\big)h$. Then $\operatorname{\mathds{E}}\big(F_r(K_0)\big)=0$ and
	\begin{align*}
		\left\VertF-F_r\right\Vert_{(T)}
		\leqslant\sup_{\left\Vertx\right\Vert_F\geqslant r}\left\vertF(x)\right\vert e^{-T\xi(x)}
		+\left\vert\operatorname{\mathds{E}}\big(F(K_0)\chi_r(K_0)\big)\right\vert\,\left\Verth\right\Vert_{(T)}\to0.
	\end{align*}
	The first term vanishes by the defining little-$o$ condition. The second vanishes by dominated convergence and $\operatorname{\mathds{E}}\big(F(K_0)\big)=0$, since $\left\vertF(K_0)\right\vert\leqslant\left\VertF\right\Vert_{(T)}e^{T\xi(K_0)}$ is integrable by Lemma~\ref{lem:Zsecond}. Applying Step 1 to $F_r$ and Step 2 to $F-F_r$, and then letting $r\to\infty$, gives $U_N(F)\to0$ in $L^1$.

	\smallskip\noindent\textbf{Step 4 (general functions in $\mathcal{G}_{(T)}$).} For general $F$, define $F_0:=F-e^{\beta^2\xi-\varphi_\kappa(\beta^2)}\operatorname{\mathds{E}}\big(F(K_0)\big)$. Since $T>\beta^2$, we have $F_0\in\mathcal{G}_{(T)}$, and $\operatorname{\mathds{E}}\big(F_0(K_0)\big)=0$ by Lemma~\ref{lem:Zsecond}. By Step 3 and linearity, it remains to prove~\eqref{eq:general-CN-key} for $F=e^{\beta^2\xi}$.
	The exact identity $U_N(e^{\Lambda_N})=\mathcal{Z}_N^{(\boldsymbol{n})}\mathcal{Z}_N^{(\boldsymbol{n}')}$ and~\eqref{eq:general-pair-kernel} give
	\begin{align*}
		U_N(e^{\beta^2\xi})
		-e^{-\varphi_{\kappa,J}(\beta^2)}\mathcal{Z}_N^{(\boldsymbol{n})}\mathcal{Z}_N^{(\boldsymbol{n}')}\operatorname{\mathds{E}}\big(e^{\beta^2\xi(K_0)}\big)
		&=U_N\Big(e^{\beta^2\xi}-e^{\varphi_\kappa(\beta^2)-\varphi_{\kappa,J}(\beta^2)+\Lambda_N}\Big)\\
		&=U_N\Big(e^{\beta^2\xi}\big(1-e^{\mathfrak{R}_N^{(2)}}\big)\Big),
	\end{align*}
	where the pair arguments of $\Lambda_N$ and $\mathfrak{R}_N^{(2)}$ are suppressed. As in Step 2,
	\begin{align*}
		\operatorname{\mathds{E}}\Big(\Big|U_N\Big(e^{\beta^2\xi}\big(1-e^{\mathfrak{R}_N^{(2)}}\big)\Big)\Big|\Big)
		\leqslant\operatorname{\mathds{E}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}\Big(
		e^{\beta^2\xi(\mathscr{R})}\,\left\vert1-e^{\mathfrak{R}_N^{(2)}(\boldsymbol{\sigma},\boldsymbol{\tau})}\right\vert\Big)\to0.
	\end{align*}
	Here we used that $\mathfrak{R}_N^{(2)}$ is uniformly bounded and tends to zero in probability (Lemma~\ref{lem:general-kernels}), and that $e^{\beta^2\xi(\mathscr{R})}$ is uniformly integrable (Lemma~\ref{lem:profile-moments}(i) with exponent $T>\beta^2$). The convergence is uniform over the window, since all arguments apply along every sequence of profiles.

We first work with the truncated disorder. Let $f$ be a bounded continuous function of the overlap, and apply Lemma~\ref{lem:general-CN-key} to $F(x):=e^{\beta^2\xi(x)}f(x)$, which lies in $\mathcal{G}_{(T)}$ for every $T\in(\beta^2,\alpha_c(\kappa))$. Replacing $e^{\Lambda_N}$ by $e^{\varphi_{\kappa,J}(\beta^2)-\varphi_\kappa(\beta^2)+\beta^2\xi}$ as in Step 4 of that proof, and using~\eqref{eq:gaussian-tilt}, we obtain, uniformly over any fixed profile window,
	\begin{align}
		&\operatorname{\mathds{E}}_{\boldsymbol{\sigma},\boldsymbol{\tau}}^{(\boldsymbol{n}),(\boldsymbol{n}')}
			\Big( e_N(\boldsymbol{\sigma}) e_N(\boldsymbol{\tau})f\big(\mathscr{R}(\boldsymbol{\sigma},\boldsymbol{\tau})\big)\Big)
		- \mathcal{Z}_N^{(\boldsymbol{n})} \mathcal{Z}_N^{(\boldsymbol{n}')}\,\operatorname{\mathds{E}}\big(f(K)\big)
			\to0\quad\text{in }L^1,
		\label{eq:general-overlap-factorization}
	\end{align}
	where $K\sim\operatorname{N}(0,\Pi\otimes\Pi/(1-\beta^2))$ as in Theorem~\ref{thm:C}. The fourth-cumulant factors have canceled.

	\emph{Balanced replicas.} Take both profiles equal to $\boldsymbol{n}^*$ with $\kappa\mid N$. By~\eqref{eq:general-profile-lognormal}, we may divide~\eqref{eq:general-overlap-factorization} by $\big( \mathcal{Z}_N^{\operatorname{bal}}\big)^2$ in probability. Since $c_N$ is constant on a profile class, the ratio is the overlap average under two independent balanced Gibbs replicas. This gives the balanced overlap limit throughout $\beta^2<\alpha_c(\kappa)$.

	\emph{Unconstrained replicas.} Let $h_1,h_2$ be bounded continuous functions on $\mathds{R}^{\kappa}$, and first restrict to $\left\Vertm_{\boldsymbol{n}}\right\Vert_2,\left\Vertm_{\boldsymbol{n}'}\right\Vert_2\leqslant L$. Multiply~\eqref{eq:general-overlap-factorization} by $P_{\boldsymbol{n}} P_{\boldsymbol{n}'}w_{\boldsymbol{n}}w_{\boldsymbol{n}'}h_1(m_{\boldsymbol{n}})h_2(m_{\boldsymbol{n}'})$ and sum over the two profiles. The weights $w_{\boldsymbol{n}}$ are bounded on this window, so the uniform $L^1$ convergence controls the summed error. Divide by $\big(\sum_{\boldsymbol{n}} P_{\boldsymbol{n}} w_{\boldsymbol{n}} \mathcal{Z}_N^{(\boldsymbol{n})}\big)^2$, whose inverse is bounded in probability by~\eqref{eq:general-gibbs-denominator}. Writing $\chi_L(\boldsymbol{\sigma}):=\mathds{1}\{\left\Vertm(\boldsymbol{\sigma})\right\Vert_2\leqslant L\}$, we obtain, for each fixed $L$, in probability,
	\begin{align*}
		&\Big\langle h_1(m(\boldsymbol{\sigma}^1))h_2(m(\boldsymbol{\sigma}^2))f\big(\mathscr{R}(\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2)\big)\chi_L(\boldsymbol{\sigma}^1)\chi_L(\boldsymbol{\sigma}^2)\Big\rangle_{\varrho_{N,\beta}^{\otimes2}}\\
		&\quad-\Big\langle h_1(m)\chi_L\Big\rangle_{\varrho_{N,\beta}}
		\Big\langle h_2(m)\chi_L\Big\rangle_{\varrho_{N,\beta}}\,\operatorname{\mathds{E}}\big(f(K)\big)
		\longrightarrow0.
	\end{align*}
	Removing the cutoffs changes both terms by at most a constant times $\langle\mathds{1}\{\left\Vertm\right\Vert_2>L\}\rangle_{\varrho_{N,\beta}}$. Letting $L\to\infty$ and using the tail bound~\eqref{eq:general-color-tail}, we obtain, in probability,
	\begin{align*}
		\Big\langle h_1(m(\boldsymbol{\sigma}^1))h_2(m(\boldsymbol{\sigma}^2))f\big(\mathscr{R}(\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2)\big)\Big\rangle_{\varrho_{N,\beta}^{\otimes2}}
		-\Big\langle h_1(m)\Big\rangle_{\varrho_{N,\beta}}
		\Big\langle h_2(m)\Big\rangle_{\varrho_{N,\beta}}\,\operatorname{\mathds{E}}\big(f(K)\big)
		\longrightarrow0.
	\end{align*}
	The color limits~\eqref{eq:general-color-clt} now yield
	\begin{align*}
		\Big\langle h_1(m(\boldsymbol{\sigma}^1))h_2(m(\boldsymbol{\sigma}^2))f\big(\mathscr{R}(\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2)\big)\Big\rangle_{\varrho_{N,\beta}^{\otimes2}}
		\to\operatorname{\mathds{E}}\big(h_1(g)\big)\operatorname{\mathds{E}}\big(h_2(g')\big)\operatorname{\mathds{E}}\big(f(K)\big)\quad\text{in probability},
	\end{align*}
	with $g,g',K$ independent as in Theorem~\ref{thm:C}.

	It remains to pass from products to general $F$. The marginal limits give tightness in probability of the Gibbs law of $(m(\boldsymbol{\sigma}^1),m(\boldsymbol{\sigma}^2),\mathscr{R}(\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2))$. Finite sums of products $h_1(x)h_2(y)f(z)$ form an algebra that separates points and contains the constants. By the Stone--Weierstrass theorem they approximate every continuous function uniformly on compact sets. Together with tightness, the factorization therefore proves the joint weak convergence in probability. The identity $m=\sqrt{\kappa N}(p-u)$ also gives the corresponding limit for the color fractions. Finally, the coupling~\eqref{eq:truncation-coupling} transfers all assertions to the original disorder.

\label{cor:pair-clt-general}
	Under the hypotheses of Theorem~\ref{thm:C},
	\begin{align*}
		\sqrt N\big(p(\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2)-\bar u\big)
		\Longrightarrow \frac1\kappa K
			+\frac1{\sqrt{\kappa}}
				\big(g u^{\intercal}+u(g')^{\intercal}\big)
	\end{align*}
	weakly in probability, with $g,g',K$ as in Theorem~\ref{thm:C}. The covariance between the entries $(a,b)$ and $(c,d)$ of the limit is
	\begin{align*}
		\frac{\Pi_{ac}\Pi_{bd}}{\kappa^2(1-\beta^2)}
			+\frac{\Pi_{ac}+\Pi_{bd}}{\kappa^3(1-\alpha)}.
	\end{align*}
	Indeed, the margins of $p(\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2)$ are $p(\boldsymbol{\sigma}^1)$ and $p(\boldsymbol{\sigma}^2)$, so expanding $\Pi p(\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2)\Pi$ gives the exact decomposition
	\begin{align*}
		p(\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2)-\bar u
		=\Pi p(\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2)\Pi
		+\big(p(\boldsymbol{\sigma}^1)-u\big)u^{\intercal}
		+u\big(p(\boldsymbol{\sigma}^2)-u\big)^{\intercal}.
	\end{align*}
	By~\eqref{eq:pair-profile} and~\eqref{eq:profile-mag}, multiplying by $\sqrt N$ turns the right-hand side into
	$\kappa^{-1}\mathscr{R}(\boldsymbol{\sigma}^1,\boldsymbol{\sigma}^2)
		+\kappa^{-1/2}\big(m(\boldsymbol{\sigma}^1)u^{\intercal}+u\,m(\boldsymbol{\sigma}^2)^{\intercal}\big)$.
	The claim follows from Theorem~\ref{thm:C}. The first term contributes $\Pi_{ac}\Pi_{bd}/(\kappa^2(1-\beta^2))$ to the covariance, and the two rank-one terms contribute $\Pi_{ac}/(\kappa^3(1-\alpha))$ and $\Pi_{bd}/(\kappa^3(1-\alpha))$.

\label{lem:expmoment}
	Let $W, W_1, W_2, \ldots$ be i.i.d.~mean-zero random vectors in $\mathds{R}^d$ with $\left\VertW\right\Vert_2 \leqslant b$ almost surely. Set $S_N := N^{-1/2} \sum_{i=1}^{N} W_i$, and define the \emph{optimal sub-Gaussian constant} of $W$ by
	\begin{align}
		\eta_W := \sup_{s \in \mathds{R}^d \setminus \{0\}} \frac{2 \ln \operatorname{\mathds{E}}\big(e^{\langle s, W \rangle}\big)}{\left\Verts\right\Vert_2^2}.
		\label{eq:eta-def}
	\end{align}
	Then $\eta_W \leqslant b^2$. If $\eta_W < 1$, then for every $N \geqslant 1$,
	\begin{align*}
		\operatorname{\mathds{E}}\Big( \exp\Big( \frac{1}{2} \left\VertS_N\right\Vert_2^2 \Big)\Big) \leqslant \left( 1 - \eta_W \right)^{-d/2}.
	\end{align*}

Write $F(s) := \ln \operatorname{\mathds{E}}\big(e^{\langle s, W \rangle}\big)$. By Hoeffding's lemma~\cite{Hoe63}, every mean-zero random variable $X$ with $\left\vertX\right\vert \leqslant M$ almost surely satisfies $\operatorname{\mathds{E}}(e^{X}) \leqslant e^{M^2/2}$. The variable $X = \langle s, W \rangle$ is mean-zero and satisfies $\left\vertX\right\vert \leqslant \left\Verts\right\Vert_2\, b$ by the Cauchy--Schwarz inequality. Hence $F(s) \leqslant \left\Verts\right\Vert_2^2 b^2/2$ and $\eta_W \leqslant b^2 < \infty$. By the definition of $\eta_W$,
	\begin{align}
		F(s) \leqslant \frac{\eta_W}{2} \left\Verts\right\Vert_2^2 \quad \text{for every } s \in \mathds{R}^d.
		\label{eq:subgaussian}
	\end{align}
	Now let $\zeta$ be a standard Gaussian vector in $\mathds{R}^d$, independent of $(W_i)_{i \geqslant 1}$. By the Hubbard--Stratonovich identity~\cite{Hub59}, $e^{\left\Vertx\right\Vert_2^2/2} = \operatorname{\mathds{E}}_\zeta\big(e^{\langle \zeta, x \rangle}\big)$, and by~\eqref{eq:subgaussian} with $s = \zeta/\sqrt{N}$,
	\begin{align*}
		\operatorname{\mathds{E}}\Big( \exp\Big( \frac{1}{2} \left\VertS_N\right\Vert_2^2 \Big)\Big)
		= \operatorname{\mathds{E}}_\zeta\Big(  \operatorname{\mathds{E}}_W \big( e^{\langle \zeta, S_N \rangle} \big)\Big)
		= \operatorname{\mathds{E}}_\zeta\big(  e^{N F(\zeta/\sqrt N)}\big)
		\leqslant \operatorname{\mathds{E}}_\zeta\big(  e^{\frac{\eta_W}{2} \left\Vert\zeta\right\Vert_2^2}\big)
		= \left( 1 - \eta_W \right)^{-d/2}.
	\end{align*}
	The last equality uses $\eta_W < 1$.

\label{lem:eta-dual}
	Let $W$ be a mean-zero random vector on a finite probability space $(\mathcal{X}, \pi)$, and let $\mathcal{P}(\mathcal{X})$ be the set of probability measures on $\mathcal{X}$. Then
	\begin{align*}
		\eta_W = \sup_{q \in\mathcal{P}(\mathcal{X}),\, q\neq \pi} \frac{\left\Vert\operatorname{\mathds{E}}_q(W)\right\Vert_2^2}{2  D(q  \|  \pi)}.
	\end{align*}

The Gibbs variational principle on the finite space $(\mathcal{X},\pi)$ states that, for every function $f$,
	\begin{align*}
		\ln \operatorname{\mathds{E}}_\pi\big(e^{f}\big) = \sup_{q\in\mathcal{P}(\mathcal{X})} \big[ \operatorname{\mathds{E}}_q(f) - D(q\|\pi) \big],
	\end{align*}
	see~\cite{DZ98}. Apply it to $f = \langle s, W\rangle$. By the definition~\eqref{eq:eta-def}, for every $c>0$,
	\begin{align*}
		\eta_W \leqslant c
		\Leftrightarrow \forall q, s : \langle s, \operatorname{\mathds{E}}_q(W) \rangle - \frac{c}{2}\left\Verts\right\Vert_2^2 \leqslant D(q\|\pi)
		\Leftrightarrow \forall q : \frac{\left\Vert\operatorname{\mathds{E}}_q(W)\right\Vert_2^2}{2c} \leqslant D(q\|\pi).
	\end{align*}
	The last step maximizes the quadratic function of $s$. Since this equivalence holds for every $c > 0$, the claim follows.

\label{rem:expmoment-opt}
	(a) \emph{The condition $\eta_W<1$ in Lemma~\ref{lem:expmoment} is sharp.} Write $F(s):=\ln\operatorname{\mathds{E}}\big(e^{\langle s,W\rangle}\big)$ and let $\zeta\sim\operatorname{N}(0,I_d)$. The proof of Lemma~\ref{lem:expmoment} gives the exact identity
	\begin{align*}
		\operatorname{\mathds{E}} \Big(\exp\big(\tfrac12 \left\VertS_N\right\Vert_2^2\big)\Big)=\operatorname{\mathds{E}}_\zeta\big(e^{N F(\zeta/\sqrt N)}\big).
	\end{align*}
	Suppose that $2F(s_0) > \left\Verts_0\right\Vert_2^2$ for some $s_0$. Restricting the Gaussian integral to the unit ball around $\sqrt N s_0$ and using the local Lipschitz continuity of $F$ gives
	\begin{align*}
		\operatorname{\mathds{E}} \Big(\exp \big( \tfrac12 \left\VertS_N\right\Vert_2^2 \big)\Big) \geqslant c_d\,  e^{N \left( F(s_0) - \left\Verts_0\right\Vert_2^2/2 \right) - \mathcal{O}(\sqrt N)} \to \infty.
	\end{align*}
	(b) For a Rademacher variable ($d = 1$, $W = \pm 1$), $F(s) = \ln\cosh(s) \leqslant s^2/2$ and $\eta_W = 1$. In this case~\eqref{eq:subgaussian} is the classical inequality behind the second-moment computation of~\cite{ALR87} for the SK model. Lemma~\ref{lem:eta-phi} below computes the corresponding constant for the $\kappa$-state field $\phi$.

\label{lem:eta-phi}
	Let $\Lambda(t) := \ln \operatorname{\mathds{E}}_\sigma\big(  e^{\langle t, \phi(\sigma) \rangle}\big)$ for $t \in \mathds{R}^\kappa$. Then
	\begin{align*}
		\sup_{t \neq 0} \frac{2 \Lambda(t)}{\left\Vertt\right\Vert_2^2} = \eta_\phi(\kappa) =
		\begin{cases}
			1,                                                  & \kappa = 2,    \\[2pt]
			\dfrac{\kappa(\kappa-2)}{2(\kappa-1)\ln(\kappa-1)}, & \kappa \geqslant 3.
		\end{cases}
	\end{align*}
	For $\kappa \geqslant 3$ we have $\eta_\phi(\kappa)>1$, and the supremum is attained at the $\kappa$ points $t = \tfrac{2\ln(\kappa-1)}{\kappa}\,  \phi(x_0)$, $x_0 \in [\kappa]$. The corresponding tilted law is, up to a permutation of colors, the ``one color against the rest'' profile
	\begin{align*}
		p^* = \Big( \frac{\kappa-1}{\kappa}, \frac{1}{\kappa(\kappa-1)}, \ldots, \frac{1}{\kappa(\kappa-1)} \Big).
	\end{align*}
	Equivalently, by Lemma~\ref{lem:eta-dual},
	\begin{align*}
		\frac{1}{\eta_\phi(\kappa)} = \inf_{p \neq u} \frac{2 D(p  \|  u)}{\kappa \left\Vertp - u\right\Vert_2^2},
	\end{align*}
	where the infimum runs over probability vectors $p$ on $[\kappa]$.

\emph{Case $\kappa = 2$.} Here $\phi(\sigma) = \varepsilon (1,-1)/\sqrt 2$ with $\varepsilon$ a Rademacher variable. Thus $\Lambda(t) = \ln\cosh\big( (t_1 - t_2)/\sqrt 2 \big) \leqslant (t_1-t_2)^2/4 \leqslant \left\Vertt\right\Vert_2^2/2$, and the ratio tends to $1$ along $t = (a, -a)$ as $a \to 0$. Hence the supremum equals $1$. Assume $\kappa \geqslant 3$ from now on.

	\smallskip\noindent\textbf{Step 1 (reduction to centered vectors).} We have $\langle t, \phi(\sigma) \rangle = \sqrt\kappa\,  (t_\sigma - \bar t)$ with $\bar t := \kappa^{-1}\sum_x t_x$. So $\Lambda$ depends only on the centered part $\hat t := t - \bar t\,  \mathbf{1} $, while $\left\Vert\hat t\right\Vert_2 \leqslant \left\Vertt\right\Vert_2$. We may therefore restrict to centered $t$. Writing $c := \sqrt\kappa\,  \hat t \in \mathcal{V}$, the claim becomes
	\begin{align*}
		\sup_{c \in \mathcal{V} \setminus \{0\}} Q(c) = \eta_\phi(\kappa), \quad Q(c) := \frac{2\kappa  L(c)}{\left\Vertc\right\Vert_2^2}, \quad L(c) := \ln\Big( \frac1\kappa \sum_{x} e^{c_x} \Big).
	\end{align*}

	\smallskip\noindent\textbf{Step 2 (a binary sub-problem).} For $\rho \in (0,1)$ let $\Lambda_\rho(s) := \ln\big( \rho  e^{(1-\rho)s} + (1-\rho)  e^{-\rho s} \big)$ be the cumulant generating function of a centered Bernoulli$(\rho)$ variable, and define
	\begin{align*}
		h(\rho) := \frac{2\rho(1-\rho)\ln\frac{1-\rho}{\rho}}{1 - 2\rho} \quad (\rho \neq \tfrac12), \quad h(\tfrac12) := 1.
	\end{align*}
	The optimal sub-Gaussian constant of such a variable is known exactly:
	\begin{align}
		\sup_{s \neq 0} \frac{2 \Lambda_\rho(s)}{\rho(1-\rho) s^2} = \frac{1}{h(\rho)}, \quad \text{attained at } s^* = 2\ln\tfrac{1-\rho}{\rho} \text{ for } \rho \neq \tfrac12.
		\label{eq:binary-sup}
	\end{align}
	The inequality $\Lambda_\rho(s) \leqslant \tfrac{\rho(1-\rho)}{2h(\rho)}s^2$, with the constant $\rho(1-\rho)/h(\rho) = (1-2\rho)/\big(2\ln\tfrac{1-\rho}\rho\big)$, is the Kearns--Saul inequality~\cite{KS98}. See~\cite{BK13,BM13} for complete proofs and the optimality of the constant. At $\rho = \tfrac12$ it is the classical bound $\ln\cosh(s/2) \leqslant s^2/8$. That the supremum is attained at $s^*$ follows by substitution. Indeed, $e^{s^*} = \big(\tfrac{1-\rho}\rho\big)^2$ gives $\rho e^{s^*} + 1 - \rho = \tfrac{1-\rho}\rho$, so that
	\begin{align*}
		\Lambda_\rho(s^*) = -\rho s^* + \ln\tfrac{1-\rho}{\rho} = \tfrac{1-2\rho}{2}\,  s^* = \tfrac{\rho(1-\rho)}{2h(\rho)} (s^*)^2,
	\end{align*}
	where the last step uses the definition of $h$. For $\rho = \tfrac12$ the supremum is only approached as $s \to 0$.

	\smallskip\noindent\textbf{Step 3 (two-valued reduction).} We first record the lower bound. Let $c^* := 2\ln(\kappa-1) \big( e_1 - \tfrac1\kappa \mathbf{1}  \big)$. It takes one value on a single coordinate and another value on the remaining $\kappa - 1$ coordinates. The computation of Step 4 below with $j = 1$ and the equality case of~\eqref{eq:binary-sup} give $Q(c^*) = 1/h(1/\kappa) = \eta_\phi(\kappa)$. Moreover $\eta_\phi(\kappa) > 1$ for $\kappa \geqslant 3$. With $x := \kappa - 1 > 1$ this reads $x^2 - 1 > 2x\ln x$, that is, $x - 1/x - 2\ln x > 0$. This holds since the left side vanishes at $x = 1$ and has derivative $(1 - 1/x)^2 > 0$.

	As $c \to 0$ in $\mathcal{V}$, we have $L(c) = \left\Vertc\right\Vert_2^2/(2\kappa) + \mathcal{O}(\left\Vertc\right\Vert_2^3)$ because $\sum_x c_x = 0$, so $Q(c) \to 1$. Also $L(c) \leqslant \max_x c_x \leqslant \left\Vertc\right\Vert_2$, so $Q(c) \to 0$ as $\left\Vertc\right\Vert_2 \to \infty$. Since $\sup Q \geqslant \eta_\phi(\kappa) > 1$, every maximizing sequence stays in a compact subset of $\mathcal{V} \setminus \{0\}$. Hence the supremum is attained at some $c^0 \neq 0$, which is a critical point of $Q$ on $\mathcal{V}$. Let $\nabla_{\mathcal{V}}=\Pi \nabla$ denote the gradient along $\mathcal{V}$. Since $\partial_x L(c) = e^{c_x}/\sum_y e^{c_y}$ and these $\kappa$ numbers sum to one,
	\begin{align*}
		\big( \nabla_{\mathcal{V}} L(c) \big)_x = \frac{e^{c_x}}{\sum_y e^{c_y}} - \frac1\kappa.
	\end{align*}
	The criticality condition for $Q$ reads $\nabla_{\mathcal{V}} L(c^0) = 2\big( L(c^0)/\left\Vertc^0\right\Vert_2^2 \big)\,  c^0$. Multiplying its $x$-th component by $\sum_y e^{c^0_y}$ gives
	\begin{align*}
		e^{c^0_x} = A  c^0_x + B \quad \text{for every } x \in [\kappa],
	\end{align*}
	where $A$ and $B$ depend on $c^0$ but not on $x$.
	By the strict convexity of the exponential, this equation has at most two solutions. Hence $c^0$ takes exactly two distinct values, since a single value would force $c^0 = 0$.

	\smallskip\noindent\textbf{Step 4 (lumping and optimization over $j$).} Let $c \in \mathcal{V}$ take the value $a$ on $j$ coordinates and $b$ on the remaining $\kappa - j$ coordinates, with $1 \leqslant j \leqslant \kappa - 1$ and $j a + (\kappa - j) b = 0$. Set $\rho := j/\kappa$ and $s := a - b$, so that $a = (1-\rho)s$ and $b = -\rho s$. Then
	\begin{align*}
		L(c) = \ln\big( \rho e^{a} + (1-\rho) e^{b} \big) = \Lambda_\rho(s), \quad \left\Vertc\right\Vert_2^2 = \kappa\big( \rho a^2 + (1-\rho) b^2 \big) = \kappa  \rho(1-\rho)  s^2,
	\end{align*}
	whence $Q(c) = 2\Lambda_\rho(s) / (\rho(1-\rho) s^2)$. By~\eqref{eq:binary-sup}, $\sup Q = \max_{1 \leqslant j \leqslant \kappa-1} 1/h(j/\kappa)$. Finally, $h$ is symmetric about $\tfrac12$ and strictly increasing on $(0, \tfrac12]$. Indeed, the substitution $w := 1 - 2\rho \in [0, 1)$ gives $h = (1-w^2)  \tanh^{-1}(w)/w$, and
	\begin{align*}
		\frac{d h}{d w} = \frac1w - \frac{(1+w^2)\tanh^{-1}(w)}{w^2} < 0
		\Leftrightarrow (1+w^2)\tanh^{-1}(w) > w,
	\end{align*}
	which holds for $w \in (0,1)$ since $\tanh^{-1}(w) > w$. Hence the maximum over $j$ is attained at $j = 1$ (equivalently $j = \kappa - 1$), and
	\begin{align*}
		\sup_{c} Q(c) = \frac{1}{h(1/\kappa)} = \frac{\kappa(\kappa-2)}{2(\kappa-1)\ln(\kappa-1)} = \eta_\phi(\kappa).
	\end{align*}
	The maximizer is the two-valued vector with $j = 1$ and gap $s^* = 2\ln(\kappa-1)$, namely $c^* = 2\ln(\kappa-1)(e_{x_0} - \tfrac1\kappa\mathbf{1} )$. It corresponds to $t = c^*/\sqrt\kappa = \tfrac{2\ln(\kappa-1)}{\kappa}\,  \phi(x_0)$. Its tilted law is proportional to $(e^{c^*_x})_x$, which is exactly $p^*$. Finally, the dual formula is Lemma~\ref{lem:eta-dual} applied to $\phi$ on $([\kappa], u)$, since $\operatorname{\mathds{E}}_p(\phi) = \sqrt\kappa\,  (p - u)$ and hence $\left\Vert\operatorname{\mathds{E}}_p(\phi)\right\Vert_2^2 = \kappa \left\Vertp-u\right\Vert_2^2$.

The idea is to apply~\eqref{eq:row-dual} to each conditional row and to average, using the chain rule for relative entropy. The error terms come from replacing $u$ by $p'$ and $1/p_x$ by $\kappa$. Write $p^{(x)} := q_{x\cdot}/p_x \in \mathcal{P}([\kappa])$ for the $x$-th conditional row of $q$. Since $\kappa u_y = 1$,
	\begin{align*}
		D(p^{(x)}\|p') - D(p^{(x)}\|u) = - \sum_y p^{(x)}_y \ln(\kappa p'_y) = - \kappa \big\langle p^{(x)}, p'-u \big\rangle - \sum_y p^{(x)}_y \Big( \ln(\kappa p'_y) - \kappa (p'_y - u_y) \Big).
	\end{align*}
	For the first term, the Cauchy--Schwarz inequality and $\langle u, p'-u\rangle = 0$ give
	\begin{align*}
		\left\vert\big\langle p^{(x)}, p'-u \big\rangle\right\vert
		 & = \left\vert\big\langle p^{(x)} - p',  p'-u \big\rangle + \big\langle p',  p'-u \big\rangle\right\vert \\
		 & \leqslant \left\Vertp^{(x)} - p'\right\Vert_2 \left\Vertp' - u\right\Vert_2 + \left\Vertp' - u\right\Vert_2^2
		\leqslant C\delta  \left\Vertp^{(x)} - p'\right\Vert_2 + C\delta^2.
	\end{align*}
	For the second term, note that $\ln(\kappa p'_y) = \ln\big(1 + \kappa(p'_y - u_y)\big)$ and $\left\vert\kappa(p'_y-u_y)\right\vert \leqslant \kappa\delta \leqslant \tfrac12$. Hence $\left\vert\ln(\kappa p'_y) - \kappa(p'_y - u_y)\right\vert \leqslant C\delta^2$, and $\sum_y p^{(x)}_y = 1$.
	We combine these bounds with~\eqref{eq:row-dual} and with $\left\Vertp^{(x)}-u\right\Vert_2^2 \geqslant \left\Vertp^{(x)}-p'\right\Vert_2^2 - 2\sqrt\kappa\, \delta\left\Vertp^{(x)}-p'\right\Vert_2$, which follows from $\left\Vertp'-u\right\Vert_2\leqslant\sqrt\kappa\,\delta$. This gives
	\begin{align*}
		D(p^{(x)}\|p')  \geqslant \frac{\alpha_c\kappa}{2}  \left\Vertp^{(x)}-p'\right\Vert_2^2 - C\delta  \left\Vertp^{(x)} - p'\right\Vert_2 - C\delta^2.
	\end{align*}

	Now average over rows. By the chain rule, $D(q\|p\otimes p') = \sum_x p_x  D(p^{(x)}\|p')$. Since $p^{(x)}_y - p'_y = (q_{xy} - p_x p'_y)/p_x$,
	\begin{align*}
		\sum_x p_x \left\Vertp^{(x)} - p'\right\Vert_2^2 = \sum_{x,y} \frac{w_{xy}^2}{p_x}.
	\end{align*}
	The margin bound $\kappa^{-1}(1 - \kappa\delta) \leqslant p_x \leqslant \kappa^{-1}(1 + \kappa\delta)$ bounds this quantity below by $\kappa(1-\kappa\delta)\left\Vertw\right\Vert_F^2$ and above by $C\left\Vertw\right\Vert_F^2$.
	The lower bound produces the error $\alpha_c\kappa^3\delta\left\Vertw\right\Vert_F^2/2$, which is at most $C\delta\left\Vertw\right\Vert_F$ because $\left\Vertw\right\Vert_F\leqslant\left\Vertq\right\Vert_F+\left\Vertp\otimes p'\right\Vert_F\leqslant2$. The upper bound and the Cauchy--Schwarz inequality in $x$ bound the averaged linear term by $C\delta\left\Vertw\right\Vert_F$. Together these estimates give~\eqref{eq:near-uniform}.
